# pip / rich progress lines (may arrive with \\r instead of \\n)
_RE_DOWNLOADING = re.compile(
    r"Downloading\s+(\S+)\s+\(([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)\)",
    re.I,
)
_RE_PROGRESS = re.compile(
    r"([0-9.]+)\s*/\s*([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)"
    r"(?:\s+([0-9.]+)\s*(kB|KB|KiB|MB|MiB|GB|GiB|B)/s)?",
    re.I,
)
# Offline / post-download phases emit no byte counters; stall watchers must
# still treat these as alive so unpack of ctranslate2/onnxruntime/av is not
# killed as "解析超时" (~45s) or "下载停滞" (~60s).
_RE_PIP_INSTALL_ACTIVITY = re.compile(
    r"^(?:Processing |Installing |Successfully installed|Building wheel|"
    r"Preparing metadata|Collecting |Using cached |Obtaining |"
    r"Requirement already|Looking in indexes|Looking in links|"
    r"Uninstalling |Would install|Defaulting to user installation)",
    re.I,
)
# Allow long local unpack after wheels are present (AV scan + large native wheels).
PIP_INSTALL_STALL_SEC = 600.0


def pip_line_marks_activity(line: str) -> bool:
    """True when a pip stdout line should reset the stall timer."""
    text = str(line or "").strip()
    if not text:
        return False
    if _RE_DOWNLOADING.search(text) or _RE_PROGRESS.search(text):
        return True
    return bool(_RE_PIP_INSTALL_ACTIVITY.search(text))

