def _is_skipped_auto_require(dep_name: str) -> bool:
    """True for optional FunASR paths or CUDA stacks handled elsewhere."""
    name = str(dep_name or "").strip().lower().replace("_", "-")
    if not name:
        return True
    if name in _SKIP_AUTO_REQUIRES:
        return True
    # Torch metadata lists nvidia-*-cu12 with Linux markers; never pull the CUDA
    # pip stack here — Windows GPU libs come from ensure_gpu_runtime.
    if name.startswith("nvidia-") or name.startswith("cuda-"):
        return True
    # peft / transformers Requires-Dist often list torch; never let followup or
    # plain pip replace a managed CUDA/ROCm wheel with PyPI CPU.
    if name in ("torch", "torchaudio", "torchvision") and _accel_torch_managed():
        return True
    return False


def _shared_pin_requirement(dep_name: str) -> str:
    """Engine pin that must win over an upstream wheel's Requires-Dist."""
    name = str(dep_name or "").strip().lower().replace("_", "-")
    if name == "tokenizers":
        return TOKENIZERS_PIN
    if name == "numpy":
        return NUMPY_NUMBA_PIN
    return ""


def _upstream_allows_pin(pin: str, upstream: str) -> bool:
    """True when a version allowed by ``pin`` also satisfies ``upstream``."""
    try:
        pin_req = Requirement(str(pin or "").strip())
        up_req = Requirement(str(upstream or "").strip())
    except Exception:
        return True
    if not up_req.specifier:
        return True
    try:
        from packaging.version import Version
    except Exception:
        return True
    specs = list(pin_req.specifier)
    if len(specs) == 1 and specs[0].operator == "==":
        try:
            return Version(str(specs[0].version)) in up_req.specifier
        except Exception:
            return True
    probes = ("1.26.4", "2.2.6", "2.4.6")
    try:
        return any(
            (ver := Version(text)) in pin_req.specifier and ver in up_req.specifier
            for text in probes
        )
    except Exception:
        return True


def _coerce_upstream_to_shared_pin(dep_name: str, base: str) -> str | None:
    """
    Drop or rewrite an upstream requirement that fights a shared pin.

    transformers>=5.16 metadata asks for ``tokenizers>=0.23.1,<0.24``. That range
    cannot share ``tokenizers==0.22.2`` with transformers 4.57 / 5.15. Qwen/Cohere
    stay on ``<5.16`` so a one-click repair does not upgrade then immediately
    downgrade tokenizers ("仍缺少 tokenizers…").

    Returns ``""`` when the pin is already installed (skip), the pin requirement
    when it should be installed instead, or None when ``base`` does not conflict.
    """
    pin = _shared_pin_requirement(dep_name)
    if not pin or _upstream_allows_pin(pin, base):
        return None
    if _requirement_satisfied(pin):
        return ""
    return pin


def _requirement_applies_here(req_text: str) -> bool:
    """False when the requirement's environment marker excludes this platform."""
    text = str(req_text or "").strip()
    if not text:
        return False
    try:
        req = Requirement(text)
    except Exception:
        # Fall back to ignoring markers we cannot parse.
        return True
    if req.marker is None:
        return True
    try:
        return bool(req.marker.evaluate())
    except Exception:
        return False


def _bundled_wheels_dir() -> str:
    """transub-engine/wheels next to runtime/ (optional offline find-links)."""
    here = os.path.abspath(os.path.dirname(__file__))
    # .../runtime/Lib/site-packages/transub_engine -> engine root
    engine_root = os.path.abspath(os.path.join(here, "..", "..", "..", ".."))
    candidate = os.path.join(engine_root, "wheels")
    if os.path.isdir(candidate):
        return candidate
    # Dev / alternate layouts
    alt = os.path.abspath(os.path.join(here, "..", "..", "..", "..", "..", "wheels"))
    return candidate if os.path.isdir(candidate) else (alt if os.path.isdir(alt) else "")


def _pip_find_links_args() -> list[str]:
    wheels = _bundled_wheels_dir()
    if not wheels:
        return []
    return ["--find-links", wheels]


def _onnxruntime_importable() -> bool:
    """True when Silero/WhisperSeg can import onnxruntime (CPU or GPU wheel)."""
    try:
        import onnxruntime  # noqa: F401
        return True
    except Exception:
        return False


def _torch_cuda_importable() -> bool:
    """True when a CUDA torch wheel is installed (DLL on disk).

    Does not import torch: LoadLibrary of c10_cuda.dll can hang Windows under
    Smart App Control / WDAC, and CUDA init can freeze the GPU driver.
    """
    try:
        from .device import torch_cuda_libs_present

        return bool(torch_cuda_libs_present())
    except Exception:
        return False


def _nvidia_gpu_present() -> bool:
    try:
        from .device import detect_device

        return bool(detect_device().get("hasCuda"))
    except Exception:
        return False


def _torch_family_req(req_str: str) -> bool:
    """True for bare/pinned torch or torchaudio requirements."""
    return _req_base_name(req_str) in ("torch", "torchaudio")


def _accel_torch_managed() -> bool:
    """True when this machine's torch must come from CUDA/ROCm installers, not PyPI."""
    if _nvidia_gpu_present():
        return True
    try:
        from .rocm_device import amd_gpu_present

        return bool(amd_gpu_present())
    except Exception:
        return False


def _amd_only_gpu() -> bool:
    """True when this machine is AMD Radeon without NVIDIA (ROCm path)."""
    try:
        from .rocm_device import amd_gpu_present

        return bool(amd_gpu_present()) and not _nvidia_gpu_present()
    except Exception:
        return False


def _torch_xpu_variant_mismatch() -> bool:
    """True when Intel Arc needs XPU but torch is missing, CPU, CUDA, or ROCm."""
    try:
        from .xpu_device import intel_gpu_present, torch_xpu_libs_present
    except Exception:
        return False
    if not intel_gpu_present():
        return False
    return not torch_xpu_libs_present()


def _torch_rocm_variant_mismatch() -> bool:
    """True when AMD needs ROCm but torch/torchaudio is missing, CPU, or CUDA."""
    try:
        from .rocm_device import amd_gpu_present, torch_rocm_libs_present
    except Exception:
        return False
    if not amd_gpu_present():
        return False
    if not torch_rocm_libs_present():
        return True
    try:
        from .rocm_device import amd_device_kernels_present, probe_amd_gpu

        gfx = str((probe_amd_gpu() or {}).get("gfx") or "all")
        if not amd_device_kernels_present(gfx):
            return True
    except Exception:
        pass
    torch_ver = (_pkg_version_str("torch") or "").strip().lower()
    if "+cu" in torch_ver or "+cpu" in torch_ver:
        return True
    audio_ver = (_pkg_version_str("torchaudio") or "").strip().lower()
    if not audio_ver:
        return True
    if "+rocm" not in audio_ver and ".rocm" not in audio_ver:
        return True
    # Metadata can claim +rocm while libtorchaudio.pyd fails (WinError 127).
    try:
        from .rocm_device import probe_torchaudio_import

        ok, _err = probe_torchaudio_import()
        if not ok:
            return True
    except Exception:
        return True
    return False


def _reassert_gpu_torch_after_extras(
    *,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Reinstall CUDA/ROCm torch if a later peft/transformers pip overwrote it."""
    try:
        from .rocm_device import amd_gpu_present, install_torch_rocm, torch_rocm_libs_present

        if amd_gpu_present() and (
            not torch_rocm_libs_present() or _torch_rocm_variant_mismatch()
        ):
            return install_torch_rocm(force=True, on_progress=on_progress)
    except Exception:
        pass
    try:
        from .xpu_device import install_torch_xpu, intel_gpu_present, torch_xpu_libs_present

        if intel_gpu_present() and (
            not torch_xpu_libs_present() or _torch_xpu_variant_mismatch()
        ):
            return install_torch_xpu(force=True, on_progress=on_progress)
    except Exception:
        pass
    if _nvidia_gpu_present() and (
        not _torch_cuda_importable() or _torchaudio_cuda_variant_mismatch()
    ):
        try:
            from .runtime_audio import _install_torch_cuda

            return _install_torch_cuda(force=True, on_progress=on_progress)
        except Exception as err:
            return {
                "ok": False,
                "code": "TORCH_CUDA_REQUIRED",
                "message": f"CUDA PyTorch 被覆盖后无法重装：{err}",
            }
    return {"ok": True, "skipped": True}


def _torchaudio_cuda_variant_mismatch() -> bool:
    """True when CUDA torch is on disk but torchaudio is missing / CPU / wrong +cu*.

    Metadata-only (no LoadLibrary). Catches the Qwen force-heal path that used to
    overwrite CUDA torchaudio with the PyPI CPU known wheel (same X.Y.Z, no +cu).
    """
    if not _torch_cuda_importable():
        return False
    ver = (_pkg_version_str("torchaudio") or "").strip().lower()
    if not ver:
        return True
    if "+cpu" in ver:
        return True
    if "+cu" not in ver and "+rocm" not in ver:
        return True
    try:
        from .device import installed_torch_cuda_tag

        tag = (installed_torch_cuda_tag() or "").strip().lower()
    except Exception:
        tag = ""
    if tag and tag != "cpu" and f"+{tag}" not in ver:
        return True
    return False


def _mpmath_bitcount_broken() -> bool:
    """True when mpmath is importable as a dist but libmp.bitcount is missing.

    Common after CUDA torch --no-deps leaves a half-written mpmath / sympy pair,
    or after a mirror installs pre-release ``mpmath==1.5.0a1`` (no ``bitcount``).
    """
    try:
        from mpmath.libmp import bitcount  # noqa: F401

        return False
    except Exception:
        # Dist absent → let the normal version pin handle install; only flag
        # "installed but broken" when metadata claims a version.
        return bool(_pkg_version_str("mpmath"))


def _version_matches_specifier(installed: Any, specifier: Any) -> bool:
    """True when *installed* is a PEP 440 string inside *specifier*.

    importlib.metadata.version() can return None when dist-info METADATA is
    missing the Version header; packaging.Version(None) then raises
    TypeError ('NoneType' is not iterable) instead of InvalidVersion.
    Treat blank / unparseable versions as not matching so ensure can repair.
    """
    ver = str(installed or "").strip()
    if not ver:
        return False
    if not specifier:
        return True
    try:
        return ver in specifier
    except Exception:
        return False


def _requirement_satisfied(req_str: str) -> bool:
    """True when the distribution is installed and meets the version specifier."""
    text = str(req_str or "").strip()
    if not text:
        return True
    try:
        req = Requirement(text)
    except Exception:
        return False
    name = req.name.lower().replace("_", "-")
    # Bare torch/torchaudio on a CUDA machine: CPU wheels (…+cpu) must not count
    # as satisfied — extras pip would otherwise leave Qwen/FireRed on CPU forever.
    if name in ("torch", "torchaudio") and not req.specifier and _nvidia_gpu_present():
        if not _torch_cuda_importable():
            return False
        # Hybrid: CUDA torch libs present but torchaudio is still the CPU known
        # wheel (or wrong +cu*). Treat as unsatisfied so ensure re-runs CUDA pair.
        if name == "torchaudio" and _torchaudio_cuda_variant_mismatch():
            return False
    # AMD: bare torch must be a ROCm wheel, not a CPU/CUDA leftover.
    if name in ("torch", "torchaudio") and not req.specifier and not _nvidia_gpu_present():
        try:
            from .rocm_device import amd_gpu_present, torch_rocm_libs_present

            if amd_gpu_present() and (
                not torch_rocm_libs_present() or _torch_rocm_variant_mismatch()
            ):
                return False
        except Exception:
            pass
    # CUDA --no-deps can leave a corrupt mpmath that still reports a version.
    if name == "mpmath" and _mpmath_bitcount_broken():
        return False
    # onnxruntime-gpu also provides the `onnxruntime` module; treat either as OK
    # for Whisper Silero VAD / WhisperSeg so we do not force a conflicting wheel.
    if name in ("onnxruntime", "onnxruntime-gpu") and _onnxruntime_importable():
        # GPU wheel from 「下载 GPU 支持」is often 1.21+ / 1.26+ / 1.27+, which
        # exceeds the legacy CPU pin `onnxruntime>=1.14,<1.22` in asr-whisper.
        # Accept any importable ORT GPU dist — never pip-downgrade over a live DLL.
        try:
            pkg_version("onnxruntime-gpu")
            return True
        except PackageNotFoundError:
            pass
        except Exception:
            pass
        # Still honor version pins against the CPU wheel when GPU is absent.
        installed_ver = None
        for cand in ("onnxruntime", "onnxruntime-gpu"):
            try:
                installed_ver = pkg_version(cand)
                break
            except PackageNotFoundError:
                continue
            except Exception:
                continue
        if installed_ver is None:
            return True
        if req.specifier and not _version_matches_specifier(installed_ver, req.specifier):
            return False
        return True
    try:
        installed = pkg_version(req.name)
    except PackageNotFoundError:
        if name == "onnxruntime":
            try:
                installed = pkg_version("onnxruntime-gpu")
            except PackageNotFoundError:
                return False
        else:
            return False
    except Exception:
        return False
    if req.specifier and not _version_matches_specifier(installed, req.specifier):
        return False
    return True


def _tokenizers_pin_mismatch() -> str:
    """Non-empty when installed tokenizers is outside TOKENIZERS_PIN (metadata only)."""
    if _requirement_satisfied(TOKENIZERS_PIN):
        return ""
    try:
        ver = str(pkg_version("tokenizers") or "").strip()
    except PackageNotFoundError:
        return ""
    except Exception:
        ver = "?"
    return (
        f"tokenizers {ver or '?'} 与 transformers 不兼容"
        f"（需要 {TOKENIZERS_PIN}）；一键修复会自动降级"
    )


def _tokenizers_pin_violation() -> str:
    """Non-empty when installed tokenizers breaks transformers import."""
    meta = _tokenizers_pin_mismatch()
    if meta:
        return meta
    try:
        import transformers  # noqa: F401
        return ""
    except Exception as err:
        msg = str(err).strip()
        if "tokenizers" in msg.lower():
            try:
                ver = str(pkg_version("tokenizers") or "").strip()
            except Exception:
                ver = "?"
            if _requirement_satisfied(TOKENIZERS_PIN):
                return (
                    f"tokenizers {ver} 与当前 transformers 不兼容：{msg[:240]}"
                    "；一键修复会将 transformers 降回 5.15.x（与 tokenizers==0.22.2 兼容）"
                )
            return (
                f"tokenizers {ver} 与 transformers 不兼容：{msg[:240]}"
                "；一键修复会自动安装 tokenizers==0.22.2，并把 transformers 限制在 5.15.x"
            )
        # Broken numpy METADATA (Version=None) surfaces here as found=None.
        if "found=none" in msg.lower() or "numpy" in msg.lower():
            return (
                f"transformers 导入失败（疑似 numpy 元数据损坏）：{msg[:240]}"
                "；一键修复会重装兼容 numpy / tokenizers"
            )
        return ""


def _pkg_version_str(dist_name: str) -> str | None:
    """Installed version string, or None when missing / blank METADATA Version."""
    try:
        ver = str(pkg_version(dist_name) or "").strip()
    except PackageNotFoundError:
        return None
    except Exception:
        return None
    return ver or None


def vad_whisperseg_packages() -> tuple[str, ...]:
    """WhisperSeg pins; widen huggingface-hub when transformers 5.x is already present.

    Otherwise ensure_vad_whisperseg treats hub 1.x (from Qwen3) as unsatisfied,
    force-reinstalls transformers-4.57.3, and breaks AutoModelForMultimodalLM.
    """
    hub = "huggingface-hub>=0.34.0,<1.0"
    ver = _pkg_version_str("transformers")
    if ver:
        try:
            from packaging.version import Version

            if Version(ver).major >= 5:
                hub = "huggingface-hub>=0.34.0,<2.0"
        except Exception:
            pass
    return (
        "onnxruntime>=1.14.0,<1.22",
        "transformers>=4.40.0",
        TOKENIZERS_PIN,
        hub,
        NUMPY_NUMBA_PIN,
    )


def _prefer_skip_known_wheel(requirement: str) -> bool:
    """True when the offline known wheel would downgrade a newer installed package."""
    text = str(requirement or "").strip()
    if not text or not known_wheel_satisfies_requirement(text):
        return False
    # Already satisfied — never replace with an older pinned CDN wheel.
    if _requirement_satisfied(text):
        return True
    base = _req_base_name(text).lower().replace("_", "-")
    if base != "transformers":
        return False
    installed = _pkg_version_str("transformers")
    known = known_wheel_version("transformers")
    if not installed or not known:
        return False
    try:
        from packaging.version import Version

        return Version(installed) > Version(known)
    except Exception:
        return False


def _unsatisfied_packages(packages: Sequence[str]) -> list[str]:
    missing = [
        str(p).strip()
        for p in packages
        if str(p).strip() and not _requirement_satisfied(p)
    ]
    # torch/torchaudio are often already present as --no-deps CUDA wheels, so
    # extras metadata looks complete while sympy / networkx are still absent.
    names = {_req_base_name(p) for p in packages if str(p).strip()}
    scan = [n for n in ("torch", "torchaudio") if n in names]
    if not scan:
        return missing
    seen = {m.lower() for m in missing}
    for dep in _unsatisfied_hard_requires(scan):
        key = dep.lower()
        if key in seen:
            continue
        missing.append(dep)
        seen.add(key)
    return missing


def _unsatisfied_hard_requires(dist_names: Sequence[str]) -> list[str]:
    """
    Missing hard (non-extra) requirements of packages installed with --no-deps.
    Honors environment markers (so Linux-only nvidia-* pins are not pulled on
    Windows) and skips optional / CUDA stacks listed in _SKIP_AUTO_REQUIRES.
    """
    missing: list[str] = []
    seen: set[str] = set()
    for dist in dist_names:
        name = str(dist or "").strip()
        if not name:
            continue
        try:
            reqs = pkg_requires(name) or []
        except PackageNotFoundError:
            try:
                reqs = pkg_requires(name.replace("-", "_")) or []
            except Exception:
                continue
        except Exception:
            continue
        for raw in reqs:
            text = str(raw or "").strip()
            if not text:
                continue
            low = text.lower().replace(" ", "")
            if "extra==" in low:
                continue
            if not _requirement_applies_here(text):
                continue
            try:
                req = Requirement(text)
                dep_name = req.name.lower().replace("_", "-")
                # Install without the marker clause (marker already evaluated).
                base = f"{req.name}{req.specifier}" if req.specifier else req.name
                if req.extras:
                    extras = ",".join(sorted(req.extras))
                    base = f"{req.name}[{extras}]{req.specifier}"
            except Exception:
                base = text.split(";", 1)[0].strip()
                dep_name = (
                    base.split(">", 1)[0]
                    .split("<", 1)[0]
                    .split("=", 1)[0]
                    .split("[", 1)[0]
                    .strip()
                    .lower()
                    .replace("_", "-")
                )
            if _is_skipped_auto_require(dep_name):
                continue
            coerced = _coerce_upstream_to_shared_pin(dep_name, base)
            if coerced is not None:
                if not coerced:
                    continue
                base = coerced
                dep_name = _req_base_name(base)
            key = base.lower()
            if key in seen:
                continue
            seen.add(key)
            if _requirement_satisfied(base):
                continue
            missing.append(base)
    return missing


def _uninstall_onnxruntime_cpu_if_present() -> None:
    """Remove CPU onnxruntime so onnxruntime-gpu can take over (mutually exclusive)."""
    try:
        pkg_version("onnxruntime")
    except PackageNotFoundError:
        return
    except Exception:
        return
    _log.info("uninstalling onnxruntime (CPU) before onnxruntime-gpu")
    try:
        _run_pip(["uninstall", "-y", "onnxruntime"], timeout=120)
    except Exception as err:
        _log.warning("onnxruntime uninstall failed: %s", err)


def _is_policy_blocked_error(text: str) -> bool:
    """True when Windows Smart App Control / app control policy blocked a native DLL."""
    t = str(text or "")
    low = t.lower()
    return bool(
        "应用程序控制策略" in t
        or "智能应用控制" in t
        or "smart app" in low
        or "winerror 4551" in low
        or "4551" in t
    )


def _is_dll_load_error(text: str) -> bool:
    t = str(text or "")
    low = t.lower()
    return bool(
        "dll load failed" in low
        or "找不到指定的模块" in t
        or "找不到指定的程序" in t
        or "winerror 126" in low
        or "winerror 127" in low
        or "winerror 193" in low
        or ("不是有效的" in t and "win32" in low)
        or "not a valid win32" in low
        or "_multiarray_umath" in low
    )


def _numpy_runtime_error() -> str:
    """Non-empty when numpy is missing, out of pin (<2.5), or fails native import.

    Metadata-only readiness used to treat a broken 2.5.x / wrong-arch wheel as
    "installed". That left env install stuck on DLL load / Win32 errors.
    """
    try:
        ver = str(pkg_version("numpy") or "").strip()
    except PackageNotFoundError:
        return "numpy: 未安装"
    except Exception as err:
        return f"numpy: {err}"
    if not ver:
        return "numpy: 元数据损坏（Version 为空）"
    try:
        spec = Requirement(NUMPY_NUMBA_PIN).specifier
    except Exception:
        spec = None
    if spec is not None and not _version_matches_specifier(ver, spec):
        return (
            f"numpy: {ver} 超出兼容上限（需要 {NUMPY_NUMBA_PIN}）。"
            "请强制重装 numpy-2.4.6-cp312-cp312-win_amd64.whl，"
            "或使用「手动修复」下载该 .whl 后本地安装。"
        )
    try:
        import numpy as np  # type: ignore

        live = str(getattr(np, "__version__", "") or "").strip()
        if live and spec is not None and not _version_matches_specifier(live, spec):
            return (
                f"numpy: 运行中版本 {live} 超出兼容上限（需要 {NUMPY_NUMBA_PIN}）。"
                "请完全退出后重装 numpy-2.4.6-cp312-cp312-win_amd64.whl。"
            )
    except Exception as err:
        # Drop half-imported modules so a later --force-reinstall is not WinError 5.
        import sys as _sys
        for _name in list(_sys.modules):
            if _name == "numpy" or _name.startswith("numpy."):
                del _sys.modules[_name]
        msg = str(err).strip()
        return (
            f"numpy: 无法加载（{msg[:280]}）。"
            "常见于错误架构或损坏的 .whl。"
            "请完全退出 Transub 后用「手动修复」安装 "
            "numpy-2.4.6-cp312-cp312-win_amd64.whl（勿装 2.5.x）。"
        )
    return ""


def probe_asr_whisper() -> dict[str, Any]:
    """Return readiness of Whisper CT2 + Silero VAD stack.

    Metadata-only: never import av / ctranslate2 / onnxruntime / faster_whisper.
    Importing those under Smart App Control / WDAC can hang the engine process
    (Code Integrity 3077 on av*.pyd) and block /v1/models for the UI.
    """
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {
        "numpy": "",
        "av": "",
        "ctranslate2": "",
        "onnxruntime": "",
        "faster-whisper": "",
    }
    for dist, key in (
        ("numpy", "numpy"),
        ("av", "av"),
        ("ctranslate2", "ctranslate2"),
        ("onnxruntime", "onnxruntime"),
        ("faster-whisper", "faster-whisper"),
    ):
        try:
            versions[key] = str(pkg_version(dist) or "") or "ok"
        except PackageNotFoundError as err:
            # onnxruntime-gpu also provides the onnxruntime module.
            if dist == "onnxruntime":
                try:
                    versions[key] = str(pkg_version("onnxruntime-gpu") or "") or "ok"
                    continue
                except PackageNotFoundError:
                    pass
                except Exception as err2:
                    missing.append(key)
                    errors.append(f"{key}: {err2}")
                    continue
            missing.append(key)
            errors.append(f"{key}: {err}")
        except Exception as err:
            missing.append(key)
            errors.append(f"{key}: {err}")

    numpy_ver = versions["numpy"]
    av_ver = versions["av"]
    ct2_ver = versions["ctranslate2"]
    ort_ver = versions["onnxruntime"]
    fw_ver = versions["faster-whisper"]

    # Import / pin check for numpy only (av/ct2/ort stay metadata-only — SAC hangs).
    np_err = _numpy_runtime_error()
    if np_err:
        if "numpy" not in missing:
            missing.append("numpy")
        if np_err not in errors:
            errors.append(np_err)
        if not numpy_ver:
            try:
                numpy_ver = str(pkg_version("numpy") or "") or ""
                versions["numpy"] = numpy_ver
            except Exception:
                pass

    policy_blocked = any(_is_policy_blocked_error(e) for e in errors)
    dll_blocked = (not policy_blocked) and any(_is_dll_load_error(e) for e in errors)
    ready = not missing
    if ready:
        hint = (
            f"Whisper 运行库已安装（faster-whisper {fw_ver or '?'}，"
            f"ctranslate2 {ct2_ver or '?'}，onnxruntime {ort_ver or '?'}，"
            f"av {av_ver or '?'}，numpy {numpy_ver or '?'}；"
            "实际加载在转写时验证）"
        )
    elif policy_blocked:
        hint = (
            "Windows 应用程序控制策略/智能应用控制拦截了 Whisper 依赖 DLL（多为 av）。"
            "关闭该策略或将 transub-engine 目录加入排除后重试；仅重装 pip 包无法解除拦截。"
        )
    elif dll_blocked:
        hint = (
            "无法加载 Whisper / NumPy 原生 DLL（含 _multiarray_umath / Win32）。"
            "请先安装 Visual C++ 运行库；若报 NumPy 2.5+ 或 Win32，"
            "请用「手动修复」安装 numpy-2.4.6-cp312-cp312-win_amd64.whl；"
            "若仍失败请关闭「智能应用控制」后重试。"
        )
    else:
        hint = (
            "未安装 Whisper 运行库（faster-whisper / ctranslate2 / onnxruntime / av / numpy）。"
            "下载 Whisper 模型或一键修复时会自动安装；也可手动执行："
            ' runtime\\python.exe -m pip install "faster-whisper>=1.1.0" "ctranslate2>=4.0.0"'
            ' "onnxruntime>=1.14.0,<1.22" "av>=10.0.0" "numpy>=1.24.0,<2.5"'
        )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else ("policy_blocked" if policy_blocked else "need_install"),
        "installed": ready,
        "fasterWhisperVersion": fw_ver,
        "ctranslate2Version": ct2_ver,
        "onnxruntimeVersion": ort_ver,
        "avVersion": av_ver,
        "numpyVersion": numpy_ver,
        "missing": missing,
        "errors": errors,
        "policyBlocked": policy_blocked,
        "dllBlocked": dll_blocked,
        "hint": hint,
        "packages": list(EXTRA_PACKAGES["asr-whisper"]),
    }


def probe_vad_whisperseg() -> dict[str, Any]:
    """Return readiness of WhisperSeg ONNX stack (import-based)."""
    pkgs = list(vad_whisperseg_packages())
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}

    try:
        import onnxruntime as ort  # type: ignore

        versions["onnxruntime"] = str(getattr(ort, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("onnxruntime")
        errors.append(f"onnxruntime: {err}")
        versions["onnxruntime"] = ""

    tok_err = _tokenizers_pin_violation()
    if tok_err:
        missing.append("tokenizers")
        errors.append(tok_err)
        try:
            versions["tokenizers"] = str(pkg_version("tokenizers") or "").strip()
        except Exception:
            versions["tokenizers"] = ""

    try:
        import transformers  # type: ignore
        from transformers import WhisperFeatureExtractor  # noqa: F401

        versions["transformers"] = str(getattr(transformers, "__version__", "") or "") or "ok"
    except Exception as err:
        if "tokenizers" not in missing:
            missing.append("transformers")
            errors.append(f"transformers: {err}")
        versions["transformers"] = ""

    if "tokenizers" not in missing:
        try:
            import tokenizers  # type: ignore

            versions["tokenizers"] = str(getattr(tokenizers, "__version__", "") or "") or "ok"
        except Exception as err:
            missing.append("tokenizers")
            errors.append(f"tokenizers: {err}")
            versions["tokenizers"] = ""

    try:
        import numpy as np  # type: ignore

        versions["numpy"] = str(getattr(np, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("numpy")
        errors.append(f"numpy: {err}")
        versions["numpy"] = ""

    # Also surface metadata gaps (helps decide which wheels to fetch) without
    # treating a looser-but-importable numpy as a hard failure.
    meta_missing = _unsatisfied_packages(pkgs)
    ready = not missing
    hint = (
        "WhisperSeg 运行库就绪（"
        + "，".join(f"{k} {v or '?'}" for k, v in versions.items())
        + "）"
        if ready
        else (
            "未安装 WhisperSeg 运行库（onnxruntime / transformers / tokenizers / numpy）。"
            "下载 whisperseg-asmr 时会自动安装。"
        )
    )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else "need_install",
        "installed": ready,
        "missing": missing or meta_missing,
        "metaMissing": meta_missing,
        "errors": errors,
        "versions": versions,
        "hint": hint,
        "packages": pkgs,
    }


def extras_for_model_ids(model_ids: Iterable[str] | None) -> list[str]:
    """Map catalog model ids → pip extra keys needed to run them."""
    needed: list[str] = []
    seen: set[str] = set()

    def add(key: str) -> None:
        if key in seen:
            return
        seen.add(key)
        needed.append(key)

    for mid in model_ids or []:
        mid_s = str(mid or "").strip()
        if not mid_s:
            continue
        spec = get_spec(mid_s)
        backend = str(getattr(spec, "backend", "") or "").lower() if spec else ""
        low = mid_s.lower()

        if "whisperseg" in low or backend == "whisperseg":
            add("vad-whisperseg")
        # FireRedASR2 must not match the VAD substring "firered".
        if backend == "firered-asr2" or "firered-asr2" in low or "fireredasr2" in low:
            add("asr-firered-asr2")
        elif backend == "firered" or low == "firered-vad" or low == "firered":
            add("vad-firered")
        if "sensevoice" in low or backend == "sensevoice":
            add("asr-sensevoice")
        if "whisper" in low or backend == "whisper":
            # LID + Whisper ASR (exclude whisperseg-only ids already handled)
            if "whisperseg" not in low:
                add("asr-whisper")
        if backend == "reazon-k2" or "reazon" in low:
            add("asr-reazon-k2")
        if backend in ("qwen3-asr", "qwen3-asr-lora", "qwen3-align") or "qwen3" in low:
            add("asr-qwen3")
        if backend == "parakeet" or "parakeet" in low:
            add("asr-parakeet")
        if backend == "cohere-asr" or "cohere-transcribe" in low or "cohere-asr" in low:
            add("asr-cohere")

    order = {key: idx for idx, key in enumerate(_EXTRA_INSTALL_ORDER)}
    needed.sort(key=lambda k: (order.get(k, 100), k))
    return needed


def _unit_to_bytes(value: float, unit: str) -> int:
    mul = _UNIT_BYTES.get(str(unit or "b").lower(), 1.0)
    try:
        return max(0, int(float(value) * mul))
    except (TypeError, ValueError):
        return 0


def _run_pip(args: list[str], *, timeout: int = 3600) -> subprocess.CompletedProcess[str]:
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("runtime_extras pip: %s", " ".join(cmd))
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout,
        check=False,
    )


def _parse_pip_progress_line(line: str) -> dict[str, Any] | None:
    text = str(line or "").strip()
    if not text:
        return None
    m_dl = _RE_DOWNLOADING.search(text)
    if m_dl:
        name = m_dl.group(1)
        total = _unit_to_bytes(float(m_dl.group(2)), m_dl.group(3))
        return {
            "package": name,
            "downloadedBytes": 0,
            "totalBytes": total or None,
            "bytesPerSecond": None,
        }
    m_pg = _RE_PROGRESS.search(text)
    if m_pg:
        cur = _unit_to_bytes(float(m_pg.group(1)), m_pg.group(3))
        total = _unit_to_bytes(float(m_pg.group(2)), m_pg.group(3))
        speed = None
        if m_pg.group(4) and m_pg.group(5):
            speed = float(_unit_to_bytes(float(m_pg.group(4)), m_pg.group(5)))
        return {
            "downloadedBytes": cur,
            "totalBytes": total or None,
            "bytesPerSecond": speed,
        }
    return None


def _run_pip_with_progress(
    args: list[str],
    *,
    on_progress: ProgressCb | None,
    label: str,
    host: str,
    timeout: int = 3600,
    stall_sec: float = DOWNLOAD_STALL_SEC,
    resolve_stall_sec: float = PIP_RESOLVE_STALL_SEC,
) -> subprocess.CompletedProcess[str]:
    """
    Stream pip stdout/stderr so wheel download size/speed can be reported.
    Aborts the mirror when byte progress stalls (so callers can switch sources).
    """
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("runtime_extras pip: %s", " ".join(cmd))
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    env.setdefault("PIP_PROGRESS_BAR", "on")
    env.setdefault("PIP_DISABLE_PIP_VERSION_CHECK", "1")
    env.setdefault("PIP_DEFAULT_TIMEOUT", "120")

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            bufsize=1,
        )
    except OSError as err:
        return subprocess.CompletedProcess(cmd, 1, "", str(err))

    chunks: list[str] = []
    buf = ""
    current_pkg = ""
    last_emit = 0.0
    started = time.monotonic()
    state = {
        "download_started": False,
        "install_phase": False,
        "last_progress_at": started,
        "last_downloaded": -1,
        "stalled": False,
    }
    stop_watch = threading.Event()

    def flush_token(token: str) -> None:
        nonlocal current_pkg, last_emit
        token = token.strip()
        if not token:
            return
        chunks.append(token + "\n")
        # Offline wheel installs never emit Downloading lines; keep stall timer
        # alive while pip unpacks native wheels (often >45s on Windows + AV).
        if pip_line_marks_activity(token):
            state["last_progress_at"] = time.monotonic()
            if _RE_PIP_INSTALL_ACTIVITY.search(token):
                state["install_phase"] = True
                now_act = time.monotonic()
                if (now_act - last_emit) >= 0.8:
                    last_emit = now_act
                    short = token if len(token) <= 72 else (token[:69] + "…")
                    emit(
                        {
                            "type": "progress",
                            "stage": "pip",
                            "detail": f"正在解压/安装{label}（{host}）· {short}",
                            "mirror": host,
                        }
                    )
        parsed = _parse_pip_progress_line(token)
        if not parsed:
            return
        if parsed.get("package"):
            current_pkg = str(parsed["package"])
            state["download_started"] = True
            # New package line is progress once; subsequent redraws need byte growth.
            if current_pkg != state.get("_last_pkg"):
                state["_last_pkg"] = current_pkg
                state["last_progress_at"] = time.monotonic()
        downloaded = parsed.get("downloadedBytes")
        total = parsed.get("totalBytes")
        speed = parsed.get("bytesPerSecond")
        if isinstance(downloaded, (int, float)) and int(downloaded) > int(state["last_downloaded"]):
            state["last_downloaded"] = int(downloaded)
            state["last_progress_at"] = time.monotonic()
            state["download_started"] = True
        now = time.monotonic()
        pkg_changed = bool(parsed.get("package"))
        if not pkg_changed and (now - last_emit) < 0.45:
            return
        last_emit = now
        detail = f"正在安装{label}（{host}）"
        if current_pkg:
            short = current_pkg.rsplit("/", 1)[-1]
            if len(short) > 48:
                short = short[:45] + "…"
            detail = f"{detail} · {short}"
        payload: dict[str, Any] = {
            "type": "progress",
            "stage": "pip",
            "detail": detail,
            "mirror": host,
        }
        if isinstance(downloaded, (int, float)) and downloaded >= 0:
            payload["downloadedBytes"] = int(downloaded)
        if isinstance(total, (int, float)) and total > 0:
            payload["totalBytes"] = int(total)
        if isinstance(speed, (int, float)) and speed > 0:
            payload["bytesPerSecond"] = float(speed)
            if speed < 80_000 and isinstance(downloaded, (int, float)) and downloaded > 2 * 1024 * 1024:
                payload["suggestManual"] = True
        emit(payload)

    def consume_buf() -> None:
        nonlocal buf
        while True:
            cut = -1
            for sep in ("\r", "\n"):
                idx = buf.find(sep)
                if idx >= 0 and (cut < 0 or idx < cut):
                    cut = idx
            if cut < 0:
                return
            token = buf[:cut]
            buf = buf[cut + 1 :]
            flush_token(token)

    def _stall_message() -> str:
        if state.get("install_phase"):
            return f"STALL: 解压/安装停滞超过 {int(PIP_INSTALL_STALL_SEC)} 秒（镜像 {host}）"
        if state["download_started"]:
            return f"STALL: 下载停滞超过 {int(stall_sec)} 秒（镜像 {host}）"
        return f"STALL: 解析/连接停滞超过 {int(resolve_stall_sec)} 秒（镜像 {host}）"

    def _watch_stall() -> None:
        while not stop_watch.wait(2.0):
            now = time.monotonic()
            elapsed = now - started
            session_bytes = max(0, int(state["last_downloaded"]))
            age = now - float(state["last_progress_at"])
            if state.get("install_phase"):
                emit(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": (
                            f"正在解压/安装{label}（{host}）…"
                            f"已 {int(elapsed)} 秒（本地安装，请稍候）"
                        ),
                        "mirror": host,
                    }
                )
                reason = (
                    f"STALL: 解压/安装停滞超过 {int(PIP_INSTALL_STALL_SEC)} 秒"
                    if age > PIP_INSTALL_STALL_SEC
                    else None
                )
            elif not state["download_started"]:
                # Keep UI alive during long pip resolve (otherwise the last
                # "正在安装…（mirror）" line looks hung).
                emit(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": (
                            f"正在解析/连接{label}（{host}）…"
                            f"已 {int(elapsed)} 秒，超时将自动换镜像"
                        ),
                        "mirror": host,
                        "suggestManual": elapsed >= max(20.0, resolve_stall_sec * 0.6),
                    }
                )
                reason = (
                    f"STALL: 解析/连接停滞超过 {int(resolve_stall_sec)} 秒"
                    if age > resolve_stall_sec
                    else None
                )
            else:
                reason = transfer_should_abort(
                    elapsed_sec=elapsed,
                    session_bytes=session_bytes if session_bytes > 0 else 0,
                    last_progress_age_sec=age,
                    stall_sec=stall_sec,
                )
            if not reason:
                continue
            state["stalled"] = True
            state["stall_reason"] = reason
            try:
                proc.kill()
            except Exception:
                pass
            return

    watch = threading.Thread(target=_watch_stall, name=f"pip-stall-{host}", daemon=True)
    watch.start()
    try:
        assert proc.stdout is not None
        while True:
            now = time.monotonic()
            if timeout > 0 and (now - started) > timeout:
                proc.kill()
                try:
                    proc.wait(timeout=5)
                except Exception:
                    pass
                raise subprocess.TimeoutExpired(cmd, timeout)
            if state["stalled"]:
                break
            block = proc.stdout.read(4096)
            if not block:
                break
            # Do NOT reset stall timer on arbitrary stdout — pip can spam the same
            # progress line forever while the socket is hung.
            buf += block
            consume_buf()
        if buf.strip():
            flush_token(buf)
            buf = ""
        if state["stalled"]:
            msg = str(state.get("stall_reason") or _stall_message())
            chunks.append(msg + "\n")
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"{host} 过慢/停滞，自动切换下一镜像…",
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            return subprocess.CompletedProcess(cmd, 1, "".join(chunks), msg)
        returncode = proc.wait(timeout=30)
    except subprocess.TimeoutExpired:
        raise
    except Exception as err:
        try:
            proc.kill()
        except Exception:
            pass
        return subprocess.CompletedProcess(cmd, 1, "".join(chunks), str(err))
    finally:
        stop_watch.set()
        try:
            watch.join(timeout=1.0)
        except Exception:
            pass

    combined = "".join(chunks)
    return subprocess.CompletedProcess(cmd, returncode, combined, "")


def _req_base_name(req_str: str) -> str:
    text = str(req_str or "").strip()
    if not text:
        return ""
    try:
        return Requirement(text).name.lower().replace("_", "-")
    except Exception:
        return (
            text.split(">", 1)[0]
            .split("<", 1)[0]
            .split("=", 1)[0]
            .split("[", 1)[0]
            .strip()
            .lower()
            .replace("_", "-")
        )


def _nodeps_followup_scan(installed_reqs: Sequence[str]) -> list[str]:
    """Names to scan after --no-deps: this pip batch plus already-present torch.

    CUDA torch is often installed in a previous extras run with --no-deps, so
    its hard Requires-Dist (sympy, networkx, …) never enter *this* followup
    unless we add torch/torchaudio to the scan list ourselves.
    """
    scan = [_req_base_name(p) for p in installed_reqs if str(p).strip()]
    have = {s.lower() for s in scan}
    for dist in ("torch", "torchaudio"):
        if dist in have:
            continue
        try:
            pkg_version(dist)
        except Exception:
            continue
        scan.append(dist)
        have.add(dist)
    return scan


def _followup_nodeps_requires(
    installed_reqs: Sequence[str],
    *,
    index_url: str,
    host: str,
    on_progress: ProgressCb | None,
    label: str,
) -> dict[str, Any]:
    """
    After --no-deps wheel installs, download any still-missing hard requires
    and install them offline. Pip is used only for extras or packages with no
    compatible binary wheel. Repeats so grandchildren of --no-deps wheels
    are fetched the same way (pip would have resolved the whole tree).
    Returns {"ok": True, "installed": [...]} or a failure dict.
    ``retryMirror`` is set when the current mirror's direct download failed.
    """
    scan = _nodeps_followup_scan(installed_reqs)
    installed_all: list[str] = []
    seen_sigs: set[tuple[str, ...]] = set()

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    from .pip_mirror_util import install_local_wheel_files

    for _round in range(6):
        unmet = _unsatisfied_hard_requires(scan)
        seen: set[str] = set()
        ordered: list[str] = []
        for u in unmet:
            key = u.lower()
            if key in seen:
                continue
            seen.add(key)
            ordered.append(u)
        if not ordered:
            return {"ok": True, "installed": installed_all}
        sig = tuple(sorted(x.lower() for x in ordered))
        if sig in seen_sigs:
            return {
                "ok": False,
                "code": "EXTRAS_INSTALL_FAILED",
                "message": f"补齐{label}传递依赖后仍缺少：{', '.join(ordered[:8])}",
                "packages": ordered,
                "suggestManual": True,
            }
        seen_sigs.add(sig)

        emit(
            {
                "type": "progress",
                "stage": "download",
                "detail": (
                    f"正在下载{label}的传递依赖（{len(ordered)} 个，"
                    "离线包装用了 --no-deps）…"
                ),
                "packages": ordered,
                "mirror": host,
            }
        )
        dl = download_requirements_direct(
            ordered,
            index_url=index_url,
            host=host,
            on_progress=on_progress,
            detail_prefix="正在下载",
        )
        if not dl.get("ok"):
            err = str(dl.get("error") or "直链下载失败")
            return {
                "ok": False,
                "retryMirror": True,
                "stalled": bool(dl.get("stalled")),
                "code": "EXTRAS_INSTALL_FAILED",
                "message": f"补齐{label}传递依赖失败：{err}",
                "packages": ordered,
            }

        unresolved = [str(p) for p in (dl.get("unresolved") or []) if str(p).strip()]
        unresolved_keys = {p.lower() for p in unresolved}
        direct_reqs = [p for p in ordered if p.lower() not in unresolved_keys]
        local_paths = list(dl.get("localPaths") or [])
        if local_paths:
            inst = install_local_wheel_files(
                local_paths,
                on_progress=on_progress,
                detail_prefix="正在本地安装",
            )
            if not inst.get("ok"):
                err = str(inst.get("error") or "本地安装失败")
                return {
                    "ok": False,
                    "code": inst.get("code") or "EXTRAS_INSTALL_FAILED",
                    "message": (
                        f"补齐{label}传递依赖失败：{err}。"
                        "已下载的 wheel 仍在缓存，可重试或改用手动安装。"
                    ),
                    "packages": ordered,
                    "suggestManual": True,
                }
            installed_all.extend(direct_reqs)
            scan.extend(_req_base_name(p) for p in direct_reqs)

        if not unresolved:
            continue

        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": (
                    f"正在用 pip 补齐无法直链的{label}依赖"
                    f"（{len(unresolved)} 个，无兼容 wheel 或带 extras）…"
                ),
                "packages": unresolved,
                "mirror": host,
            }
        )
        args = [
            "install",
            "--prefer-binary",
            "--only-binary=numba,llvmlite",
            *(_pip_find_links_args()),
            "-i",
            index_url,
            "--trusted-host",
            host,
            *unresolved,
            *_pip_keep_shared_pins(unresolved),
        ]
        # Never let unresolved peft/transformers deps replace CUDA/ROCm torch.
        if _accel_torch_managed():
            args.insert(1, "--no-deps")
        try:
            proc = _run_pip_with_progress(
                args,
                on_progress=on_progress,
                label=f"{label} deps",
                host=host,
            )
        except Exception as err:
            return {
                "ok": False,
                "code": "EXTRAS_INSTALL_FAILED",
                "message": f"补齐{label}传递依赖失败：{err}",
                "packages": unresolved,
            }
        if proc.returncode != 0:
            err = (proc.stdout or "")[-2000:] or (proc.stderr or "")[-2000:] or "pip failed"
            return {
                "ok": False,
                "code": "EXTRAS_INSTALL_FAILED",
                "message": f"补齐{label}传递依赖失败：{err}",
                "packages": unresolved,
            }
        installed_all.extend(unresolved)
        scan.extend(_req_base_name(p) for p in unresolved)

    left = _unsatisfied_hard_requires(scan)
    if left:
        return {
            "ok": False,
            "code": "EXTRAS_INSTALL_FAILED",
            "message": f"补齐{label}传递依赖未完成：{', '.join(left[:8])}",
            "packages": left,
            "suggestManual": True,
        }
    return {"ok": True, "installed": installed_all}


def _with_numpy_numba_constraint(pkgs: list[str]) -> list[str]:
    """Keep numpy <2.5 when (re)installing other deps so pip cannot float to 2.5+.

    Installing only transformers/torch without an explicit numpy pin upgrades to
    numpy 2.5.x; librosa→numba then fails every ASR window.
    """
    out = [str(p).strip() for p in pkgs if str(p).strip()]
    if not out:
        return out
    if any(_req_base_name(p) == "numpy" for p in out):
        return out
    # Already within the numba ceiling — do not force-reinstall numpy alongside
    # unrelated pins (e.g. tokenizers drift after another ASR model).
    if _requirement_satisfied(NUMPY_NUMBA_PIN):
        return out
    out.append(NUMPY_NUMBA_PIN)
    return out


def _with_tokenizers_pin_constraint(pkgs: Sequence[str]) -> list[str]:
    """Keep tokenizers==0.22.2 when installing transformers 5.x from the index."""
    out = [str(p).strip() for p in pkgs if str(p).strip()]
    if not out:
        return out
    if any(_req_base_name(p) == "tokenizers" for p in out):
        return out
    if _requirement_satisfied(TOKENIZERS_PIN):
        return out
    out.append(TOKENIZERS_PIN)
    return out


def _pip_keep_shared_pins(install_targets: Sequence[str]) -> list[str]:
    """
    Always pass numpy / tokenizers pins on index installs.

    Direct-whl can land the pinned files first, then ``pip install transformers>=5.13``
    (or peft / huggingface-hub) floats tokenizers to 0.23.x and numpy to 2.5.x.
    Repeating the pins in the same pip command is the only reliable ceiling.
    """
    names = {_req_base_name(p) for p in install_targets if str(p).strip()}
    extra: list[str] = []
    if "numpy" not in names:
        extra.append(NUMPY_NUMBA_PIN)
    if "tokenizers" not in names:
        extra.append(TOKENIZERS_PIN)
    return extra


def _reassert_shared_runtime_pins(
    *,
    on_progress: ProgressCb | None = None,
    label: str = "共享运行库 pin",
) -> dict[str, Any]:
    """Force numpy<2.5 and tokenizers==0.22.2 after a pip that may have floated them."""
    need: list[str] = []
    if not _requirement_satisfied(NUMPY_NUMBA_PIN):
        need.append(NUMPY_NUMBA_PIN)
    if not _requirement_satisfied(TOKENIZERS_PIN):
        need.append(TOKENIZERS_PIN)
    if not need:
        return {"ok": True, "skipped": True, "installed": []}
    return _install_packages(
        need,
        force=True,
        on_progress=on_progress,
        label=label,
        reassert_pins=False,
    )


def _install_packages(
    packages: tuple[str, ...] | list[str],
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
    label: str = "依赖",
    reassert_pins: bool = True,
) -> dict[str, Any]:
    requested = [str(p).strip() for p in packages if str(p).strip()]
    if not requested:
        return {"ok": True, "installed": [], "skipped": True}

    def _ok(payload: dict[str, Any]) -> dict[str, Any]:
        # peft/transformers pip can overwrite ROCm/CUDA torch — put it back first.
        accel_res = _reassert_gpu_torch_after_extras(on_progress=on_progress)
        if not accel_res.get("ok"):
            return {
                "ok": False,
                "code": accel_res.get("code") or "TORCH_ACCEL_REASSERT_FAILED",
                "message": (
                    accel_res.get("message")
                    or "GPU PyTorch 被依赖安装覆盖后重装失败"
                ),
                "torchAccel": accel_res,
                "packages": payload.get("packages") or requested,
            }
        if not accel_res.get("skipped"):
            payload = {**payload, "torchAccelReasserted": accel_res}
        if not reassert_pins:
            return payload
        pin_res = _reassert_shared_runtime_pins(on_progress=on_progress)
        if not pin_res.get("ok"):
            return pin_res
        if not pin_res.get("skipped"):
            payload = {
                **payload,
                "pinsReasserted": pin_res.get("installed") or True,
            }
        return payload

    # Avoid `pip install --upgrade` on already-satisfied pins: mirrors (esp.
    # Tsinghua) often 403 on newest wheels even when the installed version is fine.
    pkgs = list(requested) if force else _unsatisfied_packages(requested)
    # Drop offline known wheels that would downgrade a newer install (e.g. transformers
    # 5.x → CDN 4.57.3) even under force=True WhisperSeg repair.
    pkgs = [p for p in pkgs if not _prefer_skip_known_wheel(p)]
    if not pkgs:
        return {
            "ok": True,
            "installed": [],
            "skipped": True,
            "reason": "already_satisfied",
            "packages": requested,
        }

    # Never install bare torch/torchaudio from PyPI when an NVIDIA GPU is present —
    # that pulls …+cpu and leaves Qwen/Demucs crawling on CPU. Use CUDA wheels.
    # Critical: even when CUDA libs already look OK, force-heal must NOT leave
    # torch/torchaudio in the generic known-wheel path (CPU 2.11.0 overwrites
    # 2.11.0+cu126 and yields libtorchaudio.pyd WinError 127).
    # AMD: same discipline with ROCm — and never take the CUDA branch on Radeon.
    torch_pkgs = [p for p in pkgs if _torch_family_req(p)]
    amd = False
    intel = False
    install_torch_rocm = None  # type: ignore[assignment]
    torch_rocm_libs_present = None  # type: ignore[assignment]
    install_torch_xpu = None  # type: ignore[assignment]
    torch_xpu_libs_present = None  # type: ignore[assignment]
    try:
        from .rocm_device import amd_gpu_present, install_torch_rocm, torch_rocm_libs_present

        amd = bool(amd_gpu_present()) and not _nvidia_gpu_present()
    except Exception:
        amd = False
        install_torch_rocm = None  # type: ignore[assignment]
        torch_rocm_libs_present = None  # type: ignore[assignment]
    try:
        from .xpu_device import install_torch_xpu, intel_gpu_present, torch_xpu_libs_present

        intel = bool(intel_gpu_present()) and not _nvidia_gpu_present() and not amd
    except Exception:
        intel = False
        install_torch_xpu = None  # type: ignore[assignment]
        torch_xpu_libs_present = None  # type: ignore[assignment]
    if torch_pkgs and _nvidia_gpu_present() and not amd:
        try:
            from .device import torch_cuda_variant_mismatch

            need_cuda_torch = (
                not _torch_cuda_importable()
                or torch_cuda_variant_mismatch()
                or _torchaudio_cuda_variant_mismatch()
            )
        except Exception:
            need_cuda_torch = (
                not _torch_cuda_importable() or _torchaudio_cuda_variant_mismatch()
            )
    else:
        need_cuda_torch = False
    if torch_pkgs and intel and install_torch_xpu and torch_xpu_libs_present:
        need_xpu_torch = (
            not torch_xpu_libs_present() or _torch_xpu_variant_mismatch()
        )
        if need_xpu_torch:
            xpu_res = install_torch_xpu(force=True, on_progress=on_progress)
            if not xpu_res.get("ok"):
                return {
                    "ok": False,
                    "code": xpu_res.get("code") or "TORCH_XPU_INSTALL_FAILED",
                    "message": xpu_res.get("message") or "XPU PyTorch 安装失败",
                    "pipCommand": xpu_res.get("pipCommand") or "",
                }
            # Drop torch family from remaining pkgs; XPU stack already installed.
            pkgs = [p for p in pkgs if not _torch_family_req(p)]
            torch_pkgs = []
    if torch_pkgs and amd and install_torch_rocm and torch_rocm_libs_present:
        # Only (re)install when ROCm is missing or a CUDA/CPU hybrid leaked in.
        # Do NOT force-reinstall on every Qwen heal — that raced with peft pip.
        need_rocm_torch = (
            not torch_rocm_libs_present() or _torch_rocm_variant_mismatch()
        )
        if need_rocm_torch:
            if on_progress:
                try:
                    on_progress(
                        {
                            "type": "progress",
                            "stage": "pip",
                            "detail": "检测到 AMD GPU，正在把 ROCm PyTorch 装进引擎运行时…",
                            "packages": ["torch", "torchaudio"],
                        }
                    )
                except Exception:
                    pass
            rocm_res = install_torch_rocm(force=True, on_progress=on_progress)
            if not rocm_res.get("ok"):
                return {
                    "ok": False,
                    "code": rocm_res.get("code") or "TORCH_ROCM_INSTALL_FAILED",
                    "message": rocm_res.get("message") or "安装 ROCm PyTorch 失败",
                    "packages": pkgs,
                    "torchRocm": rocm_res,
                    "suggestManual": True,
                }
        else:
            try:
                from .rocm_device import probe_torchvision_import, reconcile_broken_torchvision

                if not probe_torchvision_import()[0]:
                    reconcile_broken_torchvision(on_progress=on_progress)
            except Exception:
                pass
        pkgs = [
            p
            for p in pkgs
            if _req_base_name(p) not in ("torch", "torchaudio", "torchvision")
        ]
        if not pkgs:
            return _ok({
                "ok": True,
                "installed": ["torch"],
                "skipped": not need_rocm_torch,
                "reason": (
                    "torch_rocm_already_satisfied"
                    if not need_rocm_torch
                    else ""
                ),
                "packages": requested,
                "message": "已安装 ROCm PyTorch",
            })
    if torch_pkgs and _nvidia_gpu_present() and need_cuda_torch:
        try:
            from .runtime_audio import _install_torch_cuda, _torch_cuda_runtime_lists
        except Exception as err:
            return {
                "ok": False,
                "code": "TORCH_CUDA_REQUIRED",
                "message": f"需要 CUDA 版 PyTorch，但无法加载安装器：{err}",
                "packages": pkgs,
            }
        if on_progress:
            try:
                detail_why = (
                    "torchaudio 与 CUDA PyTorch 不匹配（常见于 CPU 版覆盖）"
                    if _torch_cuda_importable() and _torchaudio_cuda_variant_mismatch()
                    else "检测到 CPU 版或版本不匹配的 PyTorch"
                )
                on_progress(
                    {
                        "type": "progress",
                        "stage": "pip",
                        "detail": (
                            f"{detail_why}，"
                            f"正在改装 CUDA（{_torch_cuda_runtime_lists()['label']}，约 2.5GB，请保持网络畅通）…"
                        ),
                        "packages": ["torch", "torchaudio"],
                    }
                )
            except Exception:
                pass
        cuda_res = _install_torch_cuda(force=True, on_progress=on_progress)
        if not cuda_res.get("ok"):
            return {
                "ok": False,
                "code": cuda_res.get("code") or "TORCH_CUDA_INSTALL_FAILED",
                "message": cuda_res.get("message")
                or "安装 CUDA PyTorch 失败（请用「手动下载」获取匹配本机 GPU 的 torch / torchaudio）",
                "packages": pkgs,
                "torchCuda": cuda_res,
                "suggestManual": True,
                "manualKind": "torch-cuda",
            }
        pkgs = [p for p in pkgs if not _torch_family_req(p)]
        if not pkgs:
            return _ok({
                "ok": True,
                "installed": list(cuda_res.get("installed") or ["torch", "torchaudio"]),
                "torchCuda": cuda_res,
            })
    elif torch_pkgs and _nvidia_gpu_present() and not amd:
        # CUDA stack already matches — drop bare torch/torchaudio so force-heal
        # cannot pull CPU known wheels over a working +cu* install.
        pkgs = [p for p in pkgs if not _torch_family_req(p)]
        if not pkgs:
            return _ok({
                "ok": True,
                "installed": [],
                "skipped": True,
                "reason": "torch_cuda_already_satisfied",
                "packages": requested,
            })

    # Batch may be transformers/peft-only after a prior wipe: restore accel torch
    # before any pip that could otherwise leave Qwen "installed" without ROCm/CUDA.
    if amd and install_torch_rocm and torch_rocm_libs_present:
        if not torch_rocm_libs_present() or _torch_rocm_variant_mismatch():
            if on_progress:
                try:
                    on_progress(
                        {
                            "type": "progress",
                            "stage": "pip",
                            "detail": "检测到 AMD GPU 但 ROCm PyTorch 缺失/被覆盖，正在重装…",
                            "packages": ["torch", "torchaudio"],
                        }
                    )
                except Exception:
                    pass
            rocm_res = install_torch_rocm(force=True, on_progress=on_progress)
            if not rocm_res.get("ok"):
                return {
                    "ok": False,
                    "code": rocm_res.get("code") or "TORCH_ROCM_INSTALL_FAILED",
                    "message": rocm_res.get("message") or "安装 ROCm PyTorch 失败",
                    "packages": pkgs,
                    "torchRocm": rocm_res,
                    "suggestManual": True,
                }
    elif _nvidia_gpu_present() and not amd and (
        not _torch_cuda_importable() or _torchaudio_cuda_variant_mismatch()
    ):
        try:
            from .runtime_audio import _install_torch_cuda, _torch_cuda_runtime_lists

            if on_progress:
                try:
                    on_progress(
                        {
                            "type": "progress",
                            "stage": "pip",
                            "detail": (
                                "检测到 CUDA PyTorch 缺失/被覆盖，"
                                f"正在重装（{_torch_cuda_runtime_lists()['label']}）…"
                            ),
                            "packages": ["torch", "torchaudio"],
                        }
                    )
                except Exception:
                    pass
            cuda_res = _install_torch_cuda(force=True, on_progress=on_progress)
            if not cuda_res.get("ok"):
                return {
                    "ok": False,
                    "code": cuda_res.get("code") or "TORCH_CUDA_INSTALL_FAILED",
                    "message": cuda_res.get("message") or "安装 CUDA PyTorch 失败",
                    "packages": pkgs,
                    "torchCuda": cuda_res,
                    "suggestManual": True,
                    "manualKind": "torch-cuda",
                }
        except Exception as err:
            return {
                "ok": False,
                "code": "TORCH_CUDA_REQUIRED",
                "message": f"需要 CUDA 版 PyTorch，但无法加载安装器：{err}",
                "packages": pkgs,
            }

    # Pin numpy / tokenizers as install targets when they already drifted.
    pkgs = _with_tokenizers_pin_constraint(_with_numpy_numba_constraint(pkgs))
    if not pkgs:
        return _ok({"ok": True, "installed": [], "skipped": True})

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    from .pip_mirror_util import preferred_mirror_from_env

    preselected = preferred_mirror_from_env()
    if not preselected:
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": f"正在测速 PyPI 镜像（索引 + 包文件吞吐，共 {len(PIP_MIRRORS)} 个）…",
                "packages": pkgs,
            }
        )
    mirrors, probe_rows, used_prefer = resolve_pip_mirror_order()
    best = mirrors[0][1] if mirrors else ""
    if used_prefer:
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": f"使用指定下载镜像 {best}（失败时自动换源）…",
                "packages": pkgs,
                "mirror": best,
                "mirrorPreferred": True,
            }
        )
    else:
        probe_summary = format_probe_summary(probe_rows)
        best_bps = best_probe_bytes_per_sec(probe_rows)
        best_speed = format_bytes_per_sec(best_bps)
        suggest = bool(best_bps > 0 and best_bps < 80_000)
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": (
                    f"镜像测速完成，优先使用 {best}"
                    + (f"（约 {best_speed}）" if best_speed else "")
                    + (f"；{probe_summary}" if probe_summary else "")
                    + ("。吞吐较低，若卡住请改用手动下载" if suggest else "")
                ),
                "packages": pkgs,
                "mirror": best,
                "mirrorProbe": probe_rows,
                "suggestManual": suggest,
            }
        )

    last_err = ""
    tried: list[str] = []

    def _finish_follow(follow: dict[str, Any]) -> dict[str, Any] | None:
        """None → try the next mirror. Otherwise return this payload to the caller."""
        nonlocal last_err
        if follow.get("ok"):
            return follow
        if follow.get("retryMirror"):
            last_err = str(follow.get("message") or "依赖直链失败")
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"{last_err}，自动切换下一镜像…",
                    "packages": pkgs,
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            return None
        return {
            **follow,
            "mirrorsTried": tried,
            "mirrorProbe": probe_rows,
            "suggestManual": bool(follow.get("suggestManual", True)),
        }

    for index_url, host in mirrors:
        tried.append(host)
        local_paths: list[str] = []
        other_pkgs: list[str] = []

        # Every requirement: resumable HTTP (pinned hash or simple-index wheel),
        # then offline pip. Pip's own downloader is only for extras / no binary wheel.
        emit(
            {
                "type": "progress",
                "stage": "download",
                "detail": f"正在下载{label}（{host}，可断点续传）…",
                "packages": pkgs,
                "mirror": host,
            }
        )
        dl = download_requirements_direct(
            pkgs,
            index_url=index_url,
            host=host,
            on_progress=on_progress,
            detail_prefix="正在下载",
        )
        if not dl.get("ok"):
            last_err = str(dl.get("error") or "直链下载失败")
            stalled = bool(dl.get("stalled"))
            if is_mirror_http_deny(last_err):
                note_mirror_denied(host)
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": (
                        f"{host} {'下载停滞' if stalled else '直链失败'}，自动切换下一镜像…"
                    ),
                    "packages": pkgs,
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            continue
        local_paths = list(dl.get("localPaths") or [])
        other_pkgs = [str(p) for p in (dl.get("unresolved") or []) if str(p).strip()]

        if local_paths and not other_pkgs:
            from .pip_mirror_util import install_local_wheel_files

            inst = install_local_wheel_files(
                local_paths,
                on_progress=on_progress,
                detail_prefix="正在本地安装",
            )
            if inst.get("ok"):
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                done = _finish_follow(follow)
                if done is None:
                    continue
                if not done.get("ok"):
                    return done
                emit(
                    {
                        "type": "progress",
                        "stage": "install",
                        "detail": f"已本地安装{label}（{host}）",
                        "packages": pkgs,
                        "mirror": host,
                        "clearTransfer": True,
                    }
                )
                return _ok({
                    "ok": True,
                    "installed": pkgs,
                    "depsInstalled": follow.get("installed") or [],
                    "mirror": host,
                    "mirrorProbe": probe_rows,
                    "method": "direct-whl",
                })
            # Offline install failed — wheels are local; do not keep re-downloading.
            last_err = str(inst.get("error") or "本地安装失败")
            return {
                "ok": False,
                "code": inst.get("code") or "EXTRAS_INSTALL_FAILED",
                "message": (
                    f"安装{label}失败：{last_err}。"
                    "文件已在本地缓存，可重试或改用「手动下载安装」。"
                ),
                "packages": pkgs,
                "mirrorsTried": tried,
                "mirrorProbe": probe_rows,
                "suggestManual": True,
                "logTail": str(inst.get("logTail") or "")[-800:],
            }

        install_targets = [*local_paths, *other_pkgs]
        if not install_targets:
            continue

        args = [
            "install",
            "--prefer-binary",
            "--only-binary=numba,llvmlite",
            *(_pip_find_links_args()),
            "-i",
            index_url,
            "--trusted-host",
            host,
            *install_targets,
            *_pip_keep_shared_pins(install_targets),
        ]
        if force:
            args.insert(1, "--upgrade")
            args.insert(2, "--force-reinstall")
        # peft/transformers pull torch from PyPI unless frozen — that wipes ROCm/CUDA.
        if _accel_torch_managed() and "--no-deps" not in args:
            args.insert(1, "--no-deps")
        # Prefer offline install for any local wheel paths mixed into the command.
        if local_paths:
            # Install cached wheels offline first, then remaining index packages.
            from .pip_mirror_util import install_local_wheel_files as _inst_local

            inst = _inst_local(
                local_paths,
                on_progress=on_progress,
                detail_prefix="正在本地安装",
            )
            if not inst.get("ok"):
                last_err = str(inst.get("error") or "本地安装失败")
                return {
                    "ok": False,
                    "code": inst.get("code") or "EXTRAS_INSTALL_FAILED",
                    "message": (
                        f"安装{label}失败：{last_err}。"
                        "已下载的 wheel 仍在缓存，可重试或改用手动安装。"
                    ),
                    "packages": pkgs,
                    "mirrorsTried": tried,
                    "mirrorProbe": probe_rows,
                    "suggestManual": True,
                    "logTail": str(inst.get("logTail") or "")[-800:],
                }
            if not other_pkgs:
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                done = _finish_follow(follow)
                if done is None:
                    continue
                if not done.get("ok"):
                    return done
                return _ok({
                    "ok": True,
                    "installed": pkgs,
                    "depsInstalled": follow.get("installed") or [],
                    "mirror": host,
                    "mirrorProbe": probe_rows,
                    "method": "direct-whl",
                })
            args = [
                "install",
                "--prefer-binary",
                "--only-binary=numba,llvmlite",
                *(_pip_find_links_args()),
                "-i",
                index_url,
                "--trusted-host",
                host,
                *other_pkgs,
                *_pip_keep_shared_pins(other_pkgs),
            ]
            if force:
                args.insert(1, "--upgrade")
                args.insert(2, "--force-reinstall")
            if _accel_torch_managed() and "--no-deps" not in args:
                args.insert(1, "--no-deps")
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": (
                    f"正在用 pip 安装无法直链的{label}"
                    f"（{host}，{len(other_pkgs)} 个）…"
                ),
                "packages": pkgs,
                "mirror": host,
            }
        )
        try:
            proc = _run_pip_with_progress(
                args,
                on_progress=on_progress,
                label=label,
                host=host,
                timeout=3600,
            )
        except subprocess.TimeoutExpired:
            last_err = f"安装{label}超时（镜像 {host}）"
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"{host} 超时，自动切换下一镜像…",
                    "packages": pkgs,
                    "mirror": host,
                    "suggestManual": True,
                }
            )
            continue
        if proc.returncode == 0:
            follow: dict[str, Any] = {"ok": True, "installed": []}
            if local_paths:
                follow = _followup_nodeps_requires(
                    pkgs,
                    index_url=index_url,
                    host=host,
                    on_progress=on_progress,
                    label=label,
                )
                done = _finish_follow(follow)
                if done is None:
                    continue
                if not done.get("ok"):
                    return done
                follow = done
            emit(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": f"已安装{label}（{host}）",
                    "packages": pkgs,
                    "mirror": host,
                }
            )
            return _ok({
                "ok": True,
                "installed": pkgs,
                "depsInstalled": follow.get("installed") or [],
                "mirror": host,
                "mirrorProbe": probe_rows,
            })
        last_err = (proc.stderr or proc.stdout or "").strip()[-1200:] or f"exit {proc.returncode}"
        denied = is_mirror_http_deny(last_err)
        if denied:
            note_mirror_denied(host)
        _log.warning(
            "pip install failed via %s%s: %s",
            host,
            " (HTTP deny/stall)" if denied else "",
            last_err[:400],
        )
        reason = "返回 403/停滞" if denied else "安装失败"
        emit(
            {
                "type": "progress",
                "stage": "pip",
                "detail": f"{host} {reason}，自动切换下一镜像…",
                "packages": pkgs,
                "mirror": host,
                "mirrorDenied": denied,
                "suggestManual": True,
            }
        )

    tried_s = " → ".join(tried) if tried else "无"
    hint = " 可改用应用内「手动下载安装」，用浏览器下载 .whl 后本地安装。"
    low = last_err.lower()
    if "numba" in low and ("failed to build" in low or "getting requirements to build" in low):
        hint = (
            " 提示：请使用 numpy<2.5 的预编译包（推荐 2.4.x）；"
            "不要安装 numpy 2.5+，否则 numba 会尝试源码编译并失败。"
        ) + hint
    return {
        "ok": False,
        "code": "EXTRAS_INSTALL_FAILED",
        "message": f"安装{label}失败（已尝试镜像：{tried_s}）。{last_err}{hint}",
        "packages": pkgs,
        "mirrorsTried": tried,
        "mirrorProbe": probe_rows,
        "suggestManual": True,
    }


def _whisper_native_modules_loaded() -> bool:
    """True when Whisper native deps are already imported in this process."""
    import sys

    return any(
        name in sys.modules
        for name in ("ctranslate2", "onnxruntime", "av", "numpy", "faster_whisper")
    )


def ensure_asr_whisper(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure faster-whisper + ctranslate2 + av + numpy for Whisper ASR / short-window LID."""
    # Prefer metadata / import checks before any --force-reinstall. Importing
    # native wheels then rewriting them in the same process fails on Windows
    # with WinError 5 (DLL still mapped).
    loaded_before = _whisper_native_modules_loaded()
    unsatisfied = list(_unsatisfied_packages(EXTRA_PACKAGES["asr-whisper"]))
    # Pin can look OK while .pyd is corrupt / wrong-arch — force numpy heal.
    # Only deep-import when metadata pin already looks satisfied.
    if NUMPY_NUMBA_PIN not in unsatisfied:
        np_err = _numpy_runtime_error()
        if np_err:
            unsatisfied.append(NUMPY_NUMBA_PIN)
        # Do NOT purge numpy after a successful diagnostic import. The native
        # extension stays mapped; dropping sys.modules makes the probe's next
        # import raise "cannot load module more than once per process". That
        # false miss plus the onnxruntime import from the requirement check
        # returns EXTRAS_LOCKED_IN_PROCESS, so a later model download aborts
        # even though the Whisper stack is already installed.
    loaded = loaded_before

    if not unsatisfied and (not force or loaded):
        probe = probe_asr_whisper()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
        if probe.get("policyBlocked"):
            return {
                **probe,
                "ok": False,
                "code": "SMART_APP_CONTROL",
                "message": str(probe.get("hint") or "应用程序控制策略拦截了 Whisper 依赖 DLL"),
            }
        if loaded or _whisper_native_modules_loaded():
            return {
                **probe,
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    "Whisper 运行库已加载于当前引擎进程，无法原地重装（Windows 会拒绝覆盖 DLL）。"
                    "请停止引擎后重试一键修复，或改用「手动安装」。"
                ),
            }
        use_force = True
    elif unsatisfied:
        use_force = False
    else:
        # force=True, metadata satisfied, nothing imported yet (offline CLI repair).
        use_force = True

    result = _install_packages(
        EXTRA_PACKAGES["asr-whisper"],
        force=use_force,
        on_progress=on_progress,
        label=" Whisper 运行库",
    )
    if not result.get("ok"):
        # Stall-kill during unpack can leave wheels already installed; prefer probe.
        probe_recover = probe_asr_whisper()
        if probe_recover.get("ready"):
            return {
                "ok": True,
                **probe_recover,
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
                "recoveredAfterInstallError": True,
                "installError": str(result.get("message") or result.get("error") or "")[:400],
            }
        if probe_recover.get("policyBlocked"):
            return {
                **probe_recover,
                "ok": False,
                "code": "SMART_APP_CONTROL",
                "message": str(probe_recover.get("hint") or "应用程序控制策略拦截了 Whisper 依赖 DLL"),
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
            }
        return result

    probe2 = probe_asr_whisper()
    if not probe2.get("ready"):
        if probe2.get("policyBlocked"):
            return {
                **probe2,
                "ok": False,
                "code": "SMART_APP_CONTROL",
                "message": str(probe2.get("hint") or "应用程序控制策略拦截了 Whisper 依赖 DLL"),
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
            }
        np_err = next(
            (e for e in (probe2.get("errors") or []) if "numpy" in str(e).lower()),
            "",
        )
        if np_err or "numpy" in (probe2.get("missing") or []):
            return {
                **probe2,
                "ok": False,
                "code": "NUMPY_DLL_BROKEN",
                "message": str(np_err or _numpy_runtime_error() or "numpy 无法加载"),
                "suggestManual": True,
                "manualKind": "whisper",
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
            }
        return {
            **probe2,
            "ok": False,
            "code": "ASR_WHISPER_VERIFY_FAILED",
            "message": (
                "已尝试安装 faster-whisper / ctranslate2 / onnxruntime / av / numpy，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            "suggestManual": True,
            "manualKind": "whisper",
        }
    return {"ok": True, **probe2, "installed": result.get("installed") or [], "mirror": result.get("mirror")}


def _whisperseg_native_modules_loaded() -> bool:
    """True when WhisperSeg native wheels are already imported in this process."""
    import sys

    return any(
        name in sys.modules
        for name in ("onnxruntime", "numpy", "tokenizers", "ctranslate2")
    )


def _purge_modules_for_reload(*roots: str) -> None:
    """Drop cached modules so a post-pip import sees the new install."""
    import sys

    roots_l = tuple(str(r or "").strip() for r in roots if str(r or "").strip())
    if not roots_l:
        return
    for name in list(sys.modules):
        for root in roots_l:
            if name == root or name.startswith(f"{root}."):
                del sys.modules[name]
                break


def ensure_vad_whisperseg(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure onnxruntime + transformers + numpy for WhisperSeg VAD."""
    pkgs_tuple = vad_whisperseg_packages()
    probe = probe_vad_whisperseg()
    if probe.get("ready"):
        # Import works — skip pip entirely (avoids re-pulling typer/rich/pygments
        # and hanging on mirrors when the stack is already bundled).
        return {
            "ok": True,
            **probe,
            "skipped": True,
            "reason": "already_ready" if force else "already_satisfied",
        }

    unsatisfied = _unsatisfied_packages(pkgs_tuple)
    loaded = _whisperseg_native_modules_loaded()
    # Native wheels already mapped in this process (typical mid-job ensure).
    # Never --force-reinstall the full stack — Windows returns WinError 5.
    native_names = frozenset(
        {"onnxruntime", "onnxruntime-gpu", "tokenizers", "numpy", "ctranslate2"}
    )

    def _base(req: str) -> str:
        return _req_base_name(req).lower().replace("_", "-")

    if unsatisfied:
        safe = [p for p in unsatisfied if _base(p) not in native_names]
        unsafe = [p for p in unsatisfied if _base(p) in native_names]
        loaded_bases = {name for name in native_names if name in sys.modules}
        # onnxruntime-gpu shares the onnxruntime module name when imported.
        if "onnxruntime" in sys.modules:
            loaded_bases.add("onnxruntime-gpu")
        unsafe_mapped = [p for p in unsafe if _base(p) in loaded_bases]
        unsafe_free = [p for p in unsafe if _base(p) not in loaded_bases]
        if unsafe_mapped and not safe and not unsafe_free:
            return {
                **probe,
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    "WhisperSeg 原生依赖已加载于当前引擎进程，无法原地重装"
                    "（Windows 会拒绝覆盖 DLL）。请停止引擎后重试一键修复，"
                    "或改用「手动安装」。"
                    f" missing={probe.get('missing')} errors={probe.get('errors')}"
                ),
            }
        # Prefer pure-Python / metadata gaps first (e.g. huggingface-hub pin).
        # Use --upgrade so an incompatible newer hub (1.x) can be downgraded.
        if loaded_bases and (safe or unsafe_free):
            install_list = [*safe, *unsafe_free]
        else:
            install_list = unsatisfied
        # force=True adds --upgrade/--force-reinstall; safe for hub/transformers
        # pure wheels, and required to replace hub 1.x with <1.
        use_force = bool(safe) and all(_base(p) not in native_names for p in install_list)
        result = _install_packages(
            install_list,
            force=use_force,
            on_progress=on_progress,
            label=" vad-whisperseg",
        )
    elif force and not loaded:
        result = _install_packages(
            pkgs_tuple,
            force=True,
            on_progress=on_progress,
            label=" vad-whisperseg",
        )
    elif loaded:
        return {
            **probe,
            "ok": False,
            "code": "EXTRAS_LOCKED_IN_PROCESS",
            "message": (
                "WhisperSeg 运行库导入失败，但依赖已加载于当前引擎进程，"
                "无法原地重装（Windows 会拒绝覆盖 DLL）。"
                "请停止引擎后重试，或改用「手动安装」。"
                f" missing={probe.get('missing')} errors={probe.get('errors')}"
            ),
        }
    else:
        # Metadata satisfied but import failed, nothing loaded yet — repair pins.
        result = _install_packages(
            pkgs_tuple,
            force=True,
            on_progress=on_progress,
            label=" vad-whisperseg",
        )

    if not result.get("ok"):
        return result

    # Hub / transformers may already be cached from the failed probe import.
    _purge_modules_for_reload("huggingface_hub", "transformers")

    probe2 = probe_vad_whisperseg()
    if not probe2.get("ready"):
        return {
            "ok": False,
            "code": "VAD_WHISPERSEG_VERIFY_FAILED",
            "message": (
                "已尝试安装 onnxruntime / transformers / tokenizers / "
                "huggingface-hub / numpy，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            **probe2,
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
        "skipped": bool(result.get("skipped")),
    }


def probe_asr_sensevoice() -> dict[str, Any]:
    """Return readiness of SenseVoice / FunASR runtime stack (import-based)."""
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}
    for mod_name, key in (
        ("numpy", "numpy"),
        ("numba", "numba"),
        ("scipy", "scipy"),
        ("librosa", "librosa"),
        ("torch", "torch"),
        ("funasr", "funasr"),
    ):
        try:
            mod = __import__(mod_name)
            versions[key] = str(getattr(mod, "__version__", "") or "") or "ok"
        except Exception as err:
            missing.append(key)
            errors.append(f"{key}: {err}")
            versions[key] = ""
    ready = not missing
    if ready:
        hint = (
            f"SenseVoice 运行库就绪（torch {versions.get('torch') or '?'}，"
            f"funasr {versions.get('funasr') or '?'}，"
            f"numba {versions.get('numba') or '?'}，scipy {versions.get('scipy') or '?'}）"
        )
    else:
        hint = (
            "未安装 SenseVoice 运行库（torch / funasr / numba / scipy / librosa / numpy）。"
            "下载 SenseVoice 模型或一键修复时会自动安装。"
        )
    return {
        "ok": True,
        "ready": ready,
        "status": "ready" if ready else "need_install",
        "installed": ready,
        "versions": versions,
        "missing": missing,
        "errors": errors,
        "hint": hint,
        "packages": list(EXTRA_PACKAGES["asr-sensevoice"]),
    }


def _sensevoice_native_modules_loaded() -> bool:
    """True when SenseVoice native deps are already imported in this process."""
    import sys

    return any(
        name in sys.modules
        for name in ("torch", "torchaudio", "numba", "llvmlite", "scipy", "funasr")
    )


def ensure_asr_sensevoice(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure FunASR SenseVoice deps (torch / numba / scipy / …)."""
    # Prefer metadata / import checks before --force-reinstall. Importing
    # torch/numba then rewriting them in the same process fails on Windows
    # with WinError 5 (DLL still mapped).
    unsatisfied = _unsatisfied_packages(EXTRA_PACKAGES["asr-sensevoice"])
    loaded = _sensevoice_native_modules_loaded()

    if not unsatisfied and (not force or loaded):
        probe = probe_asr_sensevoice()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
        if loaded or _sensevoice_native_modules_loaded():
            return {
                **probe,
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    "SenseVoice 运行库已加载于当前引擎进程，无法原地重装（Windows 会拒绝覆盖 DLL）。"
                    "请停止引擎后重试一键修复，或改用「手动安装」。"
                ),
            }
        use_force = True
    elif unsatisfied:
        use_force = False
    else:
        # force=True, metadata satisfied, nothing imported yet (offline CLI repair).
        use_force = True

    result = _install_packages(
        EXTRA_PACKAGES["asr-sensevoice"],
        force=use_force,
        on_progress=on_progress,
        label=" SenseVoice 运行库",
    )
    if not result.get("ok"):
        probe_recover = probe_asr_sensevoice()
        if probe_recover.get("ready"):
            return {
                "ok": True,
                **probe_recover,
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
                "recoveredAfterInstallError": True,
                "installError": str(result.get("message") or result.get("error") or "")[:400],
            }
        return result
    probe2 = probe_asr_sensevoice()
    if not probe2.get("ready"):
        return {
            **probe2,
            "ok": False,
            "code": "ASR_SENSEVOICE_VERIFY_FAILED",
            "message": (
                "已尝试安装 SenseVoice 运行库，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
    }


