def ensure_mt(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure ctranslate2 + transformers + sentencepiece for Opus MT."""
    unsatisfied = _unsatisfied_packages(EXTRA_PACKAGES["mt"])
    if not unsatisfied and not force:
        probe = probe_mt()
        if probe.get("ready"):
            return {"ok": True, **probe, "skipped": True, "reason": "already_satisfied"}
    result = _install_packages(
        EXTRA_PACKAGES["mt"],
        force=force and not unsatisfied,
        on_progress=on_progress,
        label=" Opus MT 运行库",
    )
    if not result.get("ok"):
        return result
    probe2 = probe_mt()
    if not probe2.get("ready"):
        return {
            **probe2,
            "ok": False,
            "code": "MT_VERIFY_FAILED",
            "message": (
                "已尝试安装 Opus MT 运行库，但仍无法导入。"
                f" missing={probe2.get('missing')} errors={probe2.get('errors')}"
            ),
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
    }



_PENDING_NUMPY_MARKER = "pending-numpy-install.json"


def _pending_numpy_marker_path():
    from pathlib import Path

    from .pip_mirror_util import wheel_cache_dir

    return wheel_cache_dir() / _PENDING_NUMPY_MARKER


def mark_pending_numpy_install(
    wheel_paths: list[str],
    *,
    source: str = "",
):
    """Record numpy wheels to install on the next cold engine start."""
    import json
    import time
    from pathlib import Path

    paths = [str(p) for p in wheel_paths if str(p).strip() and Path(str(p)).is_file()]
    marker = _pending_numpy_marker_path()
    payload = {
        "wheelPaths": paths,
        "source": str(source or ""),
        "createdAt": time.time(),
    }
    marker.parent.mkdir(parents=True, exist_ok=True)
    marker.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    _log.info("deferred numpy install (%d wheels) → %s", len(paths), marker)
    return marker


def clear_pending_numpy_install() -> None:
    marker = _pending_numpy_marker_path()
    try:
        if marker.is_file():
            marker.unlink()
    except OSError as err:
        _log.warning("clear pending numpy marker: %s", err)


def list_cached_numpy_wheels() -> list[str]:
    """Prefer pinned numpy-*-cp312-*-win_amd64.whl from the local wheel cache."""
    from pathlib import Path

    from .pip_mirror_util import known_wheel_rel, wheel_cache_dir

    cache = wheel_cache_dir()
    if not cache.is_dir():
        return []
    prefer = ""
    try:
        prefer = str(known_wheel_rel("numpy") or "").strip().lower()
        if prefer:
            prefer = Path(prefer).name.lower()
    except Exception:
        prefer = ""
    hits: list[str] = []
    for name in sorted(os.listdir(cache)):
        low = name.lower()
        if not low.endswith(".whl"):
            continue
        if not (low.startswith("numpy-") and "cp312" in low and "win_amd64" in low):
            continue
        # Skip 2.5+ filenames even if somehow cached.
        if re.search(r"numpy-2\.5", low):
            continue
        hits.append(str(cache / name))
    if not hits:
        return []
    if prefer:
        for h in hits:
            if Path(h).name.lower() == prefer:
                return [h]
    # Newest-ish last path (sorted names; 2.4.6 sorts after 2.4.0).
    return [hits[-1]]


def numpy_needs_numba_heal() -> str:
    """Non-empty reason when serve must cold-reinstall numpy (do not live-pip)."""
    from .pip_mirror_util import _dist_info_has_record

    try:
        ver = str(pkg_version("numpy") or "").strip()
    except PackageNotFoundError:
        return "numpy: 未安装"
    except Exception as err:
        return f"numpy: {err}"
    if not ver:
        return "numpy: 元数据损坏（Version 为空）"
    try:
        if not _version_matches_specifier(ver, Requirement(NUMPY_NUMBA_PIN).specifier):
            return f"numpy: {ver} 超出兼容上限（需要 {NUMPY_NUMBA_PIN}）"
    except Exception:
        pass
    try:
        rec = _dist_info_has_record("numpy")
        if rec is False:
            return "numpy: dist-info 缺少 RECORD（需冷重装）"
    except Exception:
        pass
    err = _numpy_runtime_error()
    if err:
        # Diagnostic import must not lock DLLs for a later cold install.
        _purge_modules_for_reload("numpy")
        return err
    # Do NOT purge on the healthy path. `_numpy_runtime_error` already imported
    # numpy (native `_multiarray_umath` mapped). Dropping sys.modules entries
    # leaves the extension loaded; the next import (torch → numpy) then raises
    # "cannot load module more than once per process", maps torch._C halfway,
    # and serve misreports that as Torch docstring reimport poison.
    return ""


def apply_pending_numpy_install(
    *,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Cold-install numpy from the pending marker / wheel cache.

    Must run before torch preload / any numpy import in this process.
    """
    import json
    from pathlib import Path

    if "numpy" in sys.modules:
        return {
            "ok": False,
            "skipped": True,
            "code": "NUMPY_LIVE",
            "message": "当前进程已加载 numpy，无法冷安装",
        }

    marker = _pending_numpy_marker_path()
    paths: list[str] = []
    source = "pending-marker"
    if marker.is_file():
        try:
            data = json.loads(marker.read_text(encoding="utf-8"))
        except Exception as err:
            _log.warning("read pending numpy marker: %s", err)
            data = {}
        if isinstance(data, dict):
            source = str(data.get("source") or source)
            raw = data.get("wheelPaths") or []
            if isinstance(raw, list):
                paths = [str(p) for p in raw if Path(str(p)).is_file()]
    if not paths:
        # Only cold-install when a marker was written (serve-heal / desktop).
        # Do not reinstall from cache on every boot just because a .whl sits there.
        if marker.is_file():
            paths = list_cached_numpy_wheels()
            if paths:
                source = "wheel-cache"
    if not paths:
        if marker.is_file():
            clear_pending_numpy_install()
        return {
            "ok": False,
            "skipped": True,
            "code": "NUMPY_PENDING_EMPTY",
            "message": "没有待安装的 numpy 轮子",
        }

    try:
        from .pip_mirror_util import install_local_wheel_files
    except Exception as err:
        return {
            "ok": False,
            "code": "NUMPY_COLD_INSTALL_FAILED",
            "message": f"无法加载本地轮子安装器：{err}",
        }

    inst = install_local_wheel_files(
        paths,
        on_progress=on_progress,
        detail_prefix="正在冷安装 numpy",
        timeout_sec=900.0,
    )
    if not inst.get("ok"):
        return {
            "ok": False,
            "code": "NUMPY_COLD_INSTALL_FAILED",
            "message": str(inst.get("error") or "冷安装 numpy 失败"),
            "suggestManual": True,
            "manualKind": "whisper",
        }

    np_err = _numpy_runtime_error()
    _purge_modules_for_reload("numpy")
    if np_err:
        return {
            "ok": False,
            "code": "NUMPY_DLL_BROKEN",
            "message": np_err,
            "suggestManual": True,
            "manualKind": "whisper",
        }
    clear_pending_numpy_install()
    try:
        ver = str(pkg_version("numpy") or "")
    except Exception:
        ver = ""
    return {"ok": True, "skipped": False, "version": ver, "source": source, "installed": paths}


def ensure_numpy_numba_compatible(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Downgrade numpy if it floated to 2.5+ (breaks librosa→numba)."""
    try:
        ver = pkg_version("numpy")
    except PackageNotFoundError:
        return _install_packages(
            (NUMPY_NUMBA_PIN,),
            force=True,
            on_progress=on_progress,
            label=" numpy(numba)",
        )
    except Exception as err:
        return {"ok": False, "message": f"numpy version check failed: {err}"}
    if not force and _requirement_satisfied(NUMPY_NUMBA_PIN):
        return {"ok": True, "skipped": True, "version": ver}

    # Torch preload often imports numpy first; Windows then cannot replace DLLs.
    # Still attempt disk repair (ignore-installed path), then ask for restart when
    # the live module remains out of pin.
    numpy_already_loaded = "numpy" in sys.modules
    result = _install_packages(
        (NUMPY_NUMBA_PIN,),
        force=True,
        on_progress=on_progress,
        label=" numpy(numba)",
    )
    if not result.get("ok"):
        return result
    if numpy_already_loaded:
        live = ""
        try:
            import numpy as _np  # type: ignore

            live = str(getattr(_np, "__version__", "") or "").strip()
        except Exception:
            live = ""
        if live and not _version_matches_specifier(
            live, Requirement(NUMPY_NUMBA_PIN).specifier
        ):
            return {
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    f"已写入磁盘 numpy，但当前进程仍锁定 {live}。"
                    "请完全退出应用后重新打开再检测。"
                ),
                "version": live,
                "installed": result.get("installed") or [],
            }
    # Fresh import in this process (or after purge) must succeed under the pin.
    np_err = _numpy_runtime_error()
    if np_err:
        return {
            "ok": False,
            "code": "NUMPY_DLL_BROKEN",
            "message": np_err,
            "suggestManual": True,
            "manualKind": "whisper",
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
        }
    return result


def probe_asr_qwen3() -> dict[str, Any]:
    """Return readiness of Qwen3-ASR runtime stack (metadata + CUDA torch DLL probe)."""
    missing: list[str] = []
    versions: dict[str, str] = {}
    errors: list[str] = []
    for dist, key in (
        ("numpy", "numpy"),
        ("transformers", "transformers"),
        ("torch", "torch"),
        ("torchaudio", "torchaudio"),
        ("tokenizers", "tokenizers"),
        ("numba", "numba"),
        ("huggingface-hub", "huggingface_hub"),
    ):
        ver = _pkg_version_str(dist)
        if not ver:
            missing.append(key)
            versions[key] = ""
            if dist == "numpy":
                errors.append(
                    "numpy: 元数据 Version 缺失或未安装（transformers 会报 found=None）；"
                    "一键修复会重装 numpy<2.5"
                )
        else:
            versions[key] = ver
    if versions.get("numpy") and not _requirement_satisfied(NUMPY_NUMBA_PIN):
        if "numpy" not in missing:
            missing.append("numpy")
        errors.append(
            f"numpy: {versions.get('numpy')} 超出 Numba 上限（需要 {NUMPY_NUMBA_PIN}）"
        )
    try:
        from .device import detect_device, torch_cuda_libs_present
        from .rocm_device import torch_rocm_libs_present

        info = detect_device()
        has_nvidia = bool(info.get("hasCuda"))
        has_amd = bool(info.get("hasRocm"))
        has_gpu = has_nvidia or has_amd
        torch_cuda = bool(torch_cuda_libs_present())
        torch_rocm = bool(torch_rocm_libs_present())
    except Exception:
        has_nvidia = False
        has_amd = False
        has_gpu = False
        torch_cuda = False
        torch_rocm = False

    torchaudio_mismatch = bool(
        has_nvidia and torch_cuda and _torchaudio_cuda_variant_mismatch()
    )
    if torchaudio_mismatch and "torchaudio" not in missing:
        missing.append("torchaudio")
        errors.append(
            f"torchaudio: {versions.get('torchaudio') or '?'} 与 CUDA PyTorch 不匹配"
            "（需要同版本 +cu*；一键修复会成对重装，不会装 CPU 版）"
        )
    need_cuda_torch = bool(
        has_nvidia
        and (
            (versions.get("torch") and not torch_cuda)
            or torchaudio_mismatch
        )
    )
    # AMD：缺 ROCm torch 即需修复（含完全未安装 torch）
    need_rocm_torch = bool(has_amd and not torch_rocm)
    # Metadata-only: do not import transformers here (would lock native wheels).
    tok_err = _tokenizers_pin_mismatch()
    tf_ok = True
    if versions.get("transformers") and not _requirement_satisfied(TRANSFORMERS_QWEN_PIN):
        tf_ok = False
        if "transformers" not in missing:
            missing.append("transformers")
        errors.append(
            f"transformers: {versions.get('transformers')} 超出 Qwen3 上限"
            f"（需要 {TRANSFORMERS_QWEN_PIN}，5.16+ 与 tokenizers==0.22.2 不兼容）；"
            "一键修复会降回 5.15.x"
        )
    if tok_err and "tokenizers" not in missing:
        missing.append("tokenizers")
        errors.append(tok_err)
    ready = not missing and not need_cuda_torch and not need_rocm_torch and not tok_err and tf_ok
    if ready:
        hint = (
            f"Qwen3-ASR 运行库就绪（torch {versions.get('torch') or '?'}"
            f"，transformers {versions.get('transformers') or '?'} · -hf）"
        )
        if has_nvidia and torch_cuda:
            hint += "；CUDA PyTorch 已就绪"
        elif has_amd and torch_rocm:
            hint += "；ROCm PyTorch 已就绪"
    elif tok_err:
        ready = False
        hint = tok_err
    elif not tf_ok and errors:
        ready = False
        hint = errors[0]
    elif any("numpy" in e for e in errors):
        ready = False
        hint = errors[0]
    elif need_rocm_torch:
        hint = (
            "引擎运行时缺少 ROCm 版 PyTorch。"
            "请点「自动修复」装进引擎 Python（系统 pip 无效）。"
        )
    elif need_cuda_torch and torchaudio_mismatch and torch_cuda:
        hint = (
            "CUDA PyTorch 已在磁盘，但 torchaudio 为 CPU 版或不匹配。"
            "一键修复会成对重装 CUDA 版 torch + torchaudio（约 2.5GB），不会再装 CPU 版。"
        )
    elif need_cuda_torch:
        hint = (
            "已安装 CPU 版 PyTorch，但检测到 NVIDIA GPU。"
            "下载 Qwen 模型或一键修复时会自动改装 CUDA 版（约 2.5GB）。"
            "也可使用「手动下载」→ CUDA PyTorch。"
        )
    else:
        hint = (
            "未安装 Qwen3-ASR 运行库（transformers≥5.13 / torch / numba 等）。"
            "下载 Qwen 模型或一键修复时会自动安装"
            + (
                "（AMD 需额外装 ROCm PyTorch）" if has_amd
                else ("（有 GPU 时需额外改装 CUDA 版 PyTorch，约 2.5GB）" if has_nvidia else "")
            )
            + "。"
        )
    if need_rocm_torch:
        status = "need_torch_rocm"
    elif need_cuda_torch:
        status = "need_torch_cuda"
    else:
        status = "ready" if ready else "need_install"
    return {
        "ok": True,
        "ready": ready,
        "status": status,
        "installed": ready,
        "versions": versions,
        "missing": missing,
        "errors": errors,
        "hasCudaGpu": has_nvidia,
        "hasRocm": has_amd,
        "torchCuda": torch_cuda,
        "torchRocm": torch_rocm,
        "needsTorchCuda": need_cuda_torch,
        "needsTorchRocm": need_rocm_torch,
        "hint": hint,
        "packages": list(EXTRA_PACKAGES["asr-qwen3"]),
    }


# Drop these from sys.modules after pip so the next import-based probe sees
# newly installed files. Native torch/numpy DLLs stay mapped on Windows.
# Never evict PyO3 extensions (tokenizers / safetensors): they can be
# initialized only once per interpreter — delete+reimport raises
# "may only be initialized once per interpreter process".
_QWEN3_REPROBE_PREFIXES: tuple[str, ...] = (
    "transformers",
    "huggingface_hub",
    "peft",
    "accelerate",
)
_QWEN3_PYO3_NATIVE_PREFIXES: tuple[str, ...] = (
    "tokenizers",
    "safetensors",
)


def _exception_chain_text(err: BaseException, *, limit: int = 4) -> str:
    """Unwrap transformers LazyModule wrappers so the real import cause is visible."""
    parts: list[str] = []
    seen: set[int] = set()
    cur: BaseException | None = err
    generic = "Are this object's requirements defined correctly?"
    while cur is not None and id(cur) not in seen and len(parts) < limit:
        seen.add(id(cur))
        text = str(cur).strip() or type(cur).__name__
        cause = cur.__cause__ or (
            cur.__context__ if cur.__context__ is not cur else None
        )
        if generic in text and cause is not None:
            cur = cause
            continue
        if text and text not in parts:
            parts.append(text)
        cur = cause
    return " ← ".join(parts) if parts else type(err).__name__


def _import_auto_model_for_multimodal_lm() -> None:
    """Load AutoModelForMultimodalLM without the top-level transformers LazyModule.

    ``from transformers import AutoModelForMultimodalLM`` goes through
    ``_LazyModule.__getattr__``, which wraps circular imports / missing
    backends as ``Could not import module 'AutoModelForMultimodalLM'``.
    The concrete submodule is what Qwen3-ASR actually needs.
    """
    try:
        from transformers.models.auto.modeling_auto import (  # noqa: F401
            AutoModelForMultimodalLM,
        )
    except Exception:
        from transformers import AutoModelForMultimodalLM  # noqa: F401


def _evict_imported_prefixes(prefixes: tuple[str, ...] | list[str]) -> int:
    """Remove cached imports so a post-pip probe does not reuse stale modules."""
    roots = tuple(str(p).strip() for p in prefixes if str(p).strip())
    if not roots:
        return 0
    removed = 0
    for name in list(sys.modules):
        if name in roots or any(name.startswith(p + ".") for p in roots):
            try:
                del sys.modules[name]
                removed += 1
            except Exception:
                pass
    try:
        import importlib

        importlib.invalidate_caches()
    except Exception:
        pass
    return removed


def _is_pyo3_reinit_error(text: str) -> bool:
    """True when a native PyO3 extension cannot be loaded a second time."""
    low = str(text or "").lower()
    return (
        "may only be initialized once per interpreter" in low
        or "pyo3 modules compiled" in low
    )


def _probe_is_pyo3_reinit(probe: dict[str, Any] | None) -> bool:
    """True when a runtime probe failed only because PyO3 cannot re-init."""
    if not isinstance(probe, dict):
        return False
    errors = [str(e) for e in (probe.get("errors") or []) if str(e).strip()]
    hint = str(probe.get("hint") or probe.get("message") or "")
    blob = " ".join(errors + [hint])
    return bool(errors or hint) and _is_pyo3_reinit_error(blob)


def _qwen3_repair_hint(errors: list[str], missing: list[str]) -> str:
    """Tailor the one-click-fix sentence to the actual probe failures."""
    err_text = "；".join(errors[:4]) + ("…" if len(errors) > 4 else "")
    joined = " ".join(errors).lower()
    miss = {str(m).lower() for m in missing}
    if _is_pyo3_reinit_error(joined):
        return (
            f"Qwen3-ASR 运行库未就绪（{err_text}）。"
            "tokenizers 等原生模块无法在当前进程二次初始化；"
            "请完全退出软件后重开（不必再装一遍运行库）。"
        )
    bits: list[str] = []
    if "numpy" in miss or "numpy" in joined:
        bits.append("把 numpy 降到 <2.5")
    if (
        "hiperrorinvalidimage" in joined.replace(" ", "")
        or "device kernel image is invalid" in joined
        or "kernel image is invalid" in joined
    ):
        bits.append(
            "补齐 amd-torch-device-gfx*（裸装 torch==x+rocm 没有本卡 HIP 内核；勿用 HSA_OVERRIDE 当主修复）"
        )
    if "_fblas" in joined or "scipy.linalg" in joined:
        bits.append("重装完整 scipy（含 scipy.libs/OpenBLAS）")
    if "tokenizers" in miss or "tokenizers" in joined:
        bits.append("把 tokenizers 固定为 0.22.2")
    mod_m = re.search(r"no module named ['\"]([^'\"]+)['\"]", joined)
    missing_mod = (mod_m.group(1).split(".")[0] if mod_m else "").strip()
    if "torchvision::nms" in joined or (
        "autoprocessor" in joined and "torchvision" in joined
    ):
        bits.append("修复 ROCm 版 torchvision 与 PyTorch 的匹配（或移除损坏的 torchvision）")
    if (
        "libtorchaudio" in joined
        or "torchaudio" in miss
        or ("winerror 127" in joined and "torchaudio" in joined)
        or ("找不到指定的程序" in joined and "torchaudio" in joined)
    ):
        amd = False
        try:
            from .rocm_device import amd_gpu_present

            amd = bool(amd_gpu_present()) and not _nvidia_gpu_present()
        except Exception:
            amd = False
        if amd:
            bits.append("成对重装 ROCm 版 torch + torchaudio（勿装 CUDA/CPU 版）")
        else:
            bits.append("成对重装 CUDA 版 torch + torchaudio（勿装 CPU 版）")
    if "bitcount" in joined or "mpmath" in miss or "mpmath" in joined:
        bits.append("重装 mpmath / sympy（GPU torch --no-deps 后常缺）")
    if missing_mod and missing_mod not in ("transformers", "tokenizers", "numpy", "torchaudio", "mpmath"):
        bits.append(f"补齐缺失模块 {missing_mod}")
    elif "automodelformultimodallm" in joined.replace("_", "") or "transformers" in miss:
        bits.append("重装 transformers 5.15.x")
    if not bits:
        bits.append("把 numpy 降到 <2.5、把 tokenizers 固定为 0.22.2")
    return (
        f"Qwen3-ASR 运行库未就绪（{err_text}）。"
        f"一键修复会{'、'.join(bits)}（请先停止引擎）。"
    )


def probe_asr_qwen3_runtime() -> dict[str, Any]:
    """Import-based readiness for Qwen3-ASR — skip pip when the stack already loads."""
    pkgs = list(EXTRA_PACKAGES["asr-qwen3"])
    missing: list[str] = []
    errors: list[str] = []
    versions: dict[str, str] = {}

    try:
        import numpy as np  # type: ignore

        versions["numpy"] = str(getattr(np, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("numpy")
        errors.append(f"numpy: {err}")
        versions["numpy"] = ""

    # Import can succeed while METADATA Version is blank — transformers then fails
    # with ``found=None``. Treat broken / out-of-pin numpy as needing repair.
    if "numpy" not in missing and not _requirement_satisfied(NUMPY_NUMBA_PIN):
        missing.append("numpy")
        meta_ver = _pkg_version_str("numpy") or versions.get("numpy") or "?"
        errors.append(
            f"numpy: {meta_ver} 元数据异常或超出 Numba 上限（需要 {NUMPY_NUMBA_PIN}）"
        )
        if not versions.get("numpy"):
            versions["numpy"] = meta_ver if meta_ver != "?" else ""

    try:
        import torch  # type: ignore

        versions["torch"] = str(getattr(torch, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("torch")
        errors.append(f"torch: {err}")
        versions["torch"] = ""

    # Qwen3ASRProcessor loads torchaudio; WinError 127 on libtorchaudio.pyd is the
    # classic hybrid (CPU/CUDA wheel over the wrong GPU stack). Probe it explicitly.
    try:
        import torchaudio  # type: ignore

        versions["torchaudio"] = str(getattr(torchaudio, "__version__", "") or "") or "ok"
        if _nvidia_gpu_present() and _torchaudio_cuda_variant_mismatch():
            missing.append("torchaudio")
            errors.append(
                f"torchaudio: {versions['torchaudio']} 与 CUDA PyTorch 不匹配（需要同版本 +cu* 轮子）"
            )
        elif (not _nvidia_gpu_present()) and _torch_rocm_variant_mismatch():
            missing.append("torchaudio")
            errors.append(
                f"torchaudio: {versions['torchaudio']} 与 ROCm PyTorch 不匹配（需要 +rocm*；勿装 CUDA 版）"
            )
    except Exception as err:
        missing.append("torchaudio")
        errors.append(f"torchaudio: {_exception_chain_text(err)}")
        versions["torchaudio"] = _pkg_version_str("torchaudio") or ""

    if _mpmath_bitcount_broken():
        missing.append("mpmath")
        errors.append(
            "mpmath: cannot import name 'bitcount' from 'mpmath.libmp'（CUDA torch --no-deps 后损坏）"
        )
        versions["mpmath"] = _pkg_version_str("mpmath") or "?"

    tok_err = _tokenizers_pin_violation()
    if tok_err:
        missing.append("tokenizers")
        errors.append(tok_err)
        try:
            versions["tokenizers"] = str(pkg_version("tokenizers") or "").strip()
        except Exception:
            versions["tokenizers"] = versions.get("tokenizers") or ""

    try:
        import transformers  # type: ignore

        tf_ver = str(getattr(transformers, "__version__", "") or "") or "ok"
        versions["transformers"] = tf_ver
        if not _requirement_satisfied(TRANSFORMERS_QWEN_PIN):
            missing.append("transformers")
            errors.append(f"transformers: {tf_ver} outside Qwen3 -hf pin ({TRANSFORMERS_QWEN_PIN})")
        else:
            # Native MultimodalLM path (no qwen-asr package). Import the
            # concrete auto class — top-level transformers LazyModule wraps
            # the real cause as "Could not import module AutoModelForMultimodalLM".
            try:
                _import_auto_model_for_multimodal_lm()
            except Exception as err:
                missing.append("transformers")
                errors.append(
                    f"AutoModelForMultimodalLM: {_exception_chain_text(err)}"
                )
            try:
                from transformers.models.qwen3_asr.processing_qwen3_asr import (  # noqa: F401
                    Qwen3ASRProcessor,
                )
            except Exception as err:
                missing.append("transformers")
                errors.append(
                    f"Qwen3ASRProcessor: {_exception_chain_text(err)}"
                )
    except Exception as err:
        if "transformers" not in missing:
            missing.append("transformers")
            errors.append(f"transformers: {err}")
        versions["transformers"] = ""

    if "tokenizers" not in missing and not any(_is_pyo3_reinit_error(e) for e in errors):
        try:
            import tokenizers  # type: ignore

            versions["tokenizers"] = str(getattr(tokenizers, "__version__", "") or "") or "ok"
        except Exception as err:
            missing.append("tokenizers")
            errors.append(f"tokenizers: {err}")
            versions["tokenizers"] = ""

    try:
        import numba  # type: ignore  # noqa: F401

        versions["numba"] = str(getattr(numba, "__version__", "") or "") or "ok"
    except Exception as err:
        missing.append("numba")
        errors.append(f"numba: {err}")
        versions["numba"] = ""

    try:
        from .device import detect_device, torch_cuda_libs_present
        from .rocm_device import torch_rocm_libs_present

        info = detect_device()
        has_nvidia = bool(info.get("hasCuda"))
        has_amd = bool(info.get("hasRocm"))
        has_gpu = has_nvidia or has_amd
        torch_cuda = bool(torch_cuda_libs_present())
        torch_rocm = bool(torch_rocm_libs_present())
    except Exception:
        has_nvidia = False
        has_amd = False
        has_gpu = False
        torch_cuda = False
        torch_rocm = False

    meta_missing = _unsatisfied_packages(pkgs)
    torchaudio_cuda_mismatch = bool(
        has_nvidia and torch_cuda and (
            "torchaudio" in missing or _torchaudio_cuda_variant_mismatch()
        )
    )
    torchaudio_rocm_mismatch = bool(
        has_amd and (
            "torchaudio" in missing
            or _torch_rocm_variant_mismatch()
            or any("torchaudio" in str(e).lower() for e in errors)
        )
    )
    need_cuda_torch = bool(
        has_nvidia
        and not has_amd
        and (
            (versions.get("torch") and not torch_cuda)
            or torchaudio_cuda_mismatch
        )
    )
    # AMD：缺 ROCm、或 torchaudio WinError 127 / CUDA 残留 hybrid，都走 ROCm 重装
    need_rocm_torch = bool(
        has_amd and (not torch_rocm or torchaudio_rocm_mismatch or _torch_rocm_variant_mismatch())
    )
    ready = not missing and not need_cuda_torch and not need_rocm_torch
    hint = (
        "Qwen3-ASR 运行库就绪（"
        + "，".join(f"{k} {v or '?'}" for k, v in versions.items())
        + "）"
        if ready
        else _qwen3_repair_hint(errors, missing)
    )
    if ready and has_nvidia and torch_cuda:
        hint += "；CUDA PyTorch 已就绪"
    elif ready and has_amd and torch_rocm:
        hint += "；ROCm PyTorch 已就绪"
    elif need_rocm_torch and torchaudio_rocm_mismatch and torch_rocm:
        hint = (
            "ROCm PyTorch 已在磁盘，但 torchaudio 无法加载或不匹配（常见 WinError 127 / 误装 CUDA）。"
            "一键修复会成对重装 ROCm 版 torch + torchaudio，不要装 CUDA 版。"
        )
    elif need_rocm_torch:
        hint = (
            "引擎运行时缺少 ROCm 版 PyTorch。"
            "请点「自动修复」装进引擎 Python（系统 pip 无效；AMD 勿装 CUDA 版）。"
        )
    elif need_cuda_torch and torchaudio_cuda_mismatch and torch_cuda:
        hint = (
            "CUDA PyTorch 已在磁盘，但 torchaudio 无法加载或不匹配（常见 WinError 127）。"
            "一键修复会成对重装 CUDA 版 torch + torchaudio（约 2.5GB），不会再装 CPU 版。"
        )
    elif need_cuda_torch:
        hint = (
            "已安装 CPU 版 PyTorch，但检测到 NVIDIA GPU。"
            "下载 Qwen 模型或一键修复时会自动改装 CUDA 版（约 2.5GB）。"
        )
    if need_rocm_torch:
        status = "need_torch_rocm"
    elif need_cuda_torch:
        status = "need_torch_cuda"
    else:
        status = "ready" if ready else "need_install"
    return {
        "ok": True,
        "ready": ready,
        "status": status,
        "installed": ready,
        "missing": missing or meta_missing,
        "metaMissing": meta_missing,
        "errors": errors,
        "versions": versions,
        "hasCudaGpu": has_nvidia,
        "hasRocm": has_amd,
        "torchCuda": torch_cuda,
        "torchRocm": torch_rocm,
        "needsTorchCuda": need_cuda_torch,
        "needsTorchRocm": need_rocm_torch,
        "hint": hint,
        "packages": pkgs,
    }


def _qwen3_native_modules_loaded() -> bool:
    """True when Qwen3 native deps are already imported in this process.

    ``transformers`` is pure Python and must not count as a DLL lock.
    """
    return any(
        name in sys.modules
        for name in ("torch", "torchaudio", "numba", "numpy", "tokenizers", "llvmlite")
    )


def ensure_asr_qwen3(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Ensure Qwen3-ASR deps (transformers≥5.13 / torch / numba / …).

    Metadata-first (same discipline as ``ensure_asr_whisper``): never import
    torch/transformers before deciding to pip-install, or a fresh offline
    repair process would self-lock and return EXTRAS_LOCKED_IN_PROCESS.
    """
    # Legacy qwen-asr pins transformers==4.57.6 — drop it so -hf extras can settle.
    try:
        pkg_version("qwen-asr")
        _log.info("uninstalling legacy qwen-asr before asr-qwen3 -hf ensure")
        try:
            _run_pip(["uninstall", "-y", "qwen-asr"], timeout=120)
        except Exception as err:
            _log.warning("qwen-asr uninstall failed: %s", err)
    except PackageNotFoundError:
        pass
    except Exception:
        pass

    # Capture lock state before any import-based probe.
    loaded = _qwen3_native_modules_loaded()

    # Repair broken / floated numpy first (METADATA Version=None → transformers
    # ``found=None``; 2.5+ breaks numba). Prefer doing this while DLLs are free.
    np_fix = ensure_numpy_numba_compatible(on_progress=on_progress)
    if not np_fix.get("ok"):
        return {
            "ok": False,
            "code": np_fix.get("code") or "NUMPY_NUMBA_REPAIR_FAILED",
            "message": (
                "NumPy / Numba 兼容修复失败："
                f"{np_fix.get('message') or np_fix.get('error') or 'pip error'}"
            ),
            "missing": ["numpy"],
            "errors": [str(np_fix.get("message") or "")],
        }

    pkgs = list(EXTRA_PACKAGES["asr-qwen3"])
    # Metadata-only gap list — does not import torch / transformers.
    unsatisfied = _unsatisfied_packages(pkgs)
    tok_mismatch = bool(_tokenizers_pin_mismatch())
    if tok_mismatch and not any(
        _req_base_name(p) == "tokenizers" for p in unsatisfied
    ):
        unsatisfied = [*unsatisfied, TOKENIZERS_PIN]

    native_names = frozenset(
        {"torch", "torchaudio", "tokenizers", "numpy", "numba", "llvmlite"}
    )

    if not unsatisfied and (not force or loaded):
        # Only import to verify once metadata looks good.
        probe = probe_asr_qwen3_runtime()
        if probe.get("ready"):
            return {
                "ok": True,
                **probe,
                "skipped": True,
                "reason": "already_ready" if force else "already_satisfied",
            }
        # Imports failed despite metadata OK — may still need a pin repair.
        retry_unsat = _unsatisfied_packages(pkgs)
        if not retry_unsat and loaded:
            # Natives are mapped (often just numpy from a Whisper health probe).
            # Still allow pure-Python pin heals; only hard-lock when CUDA/ROCm
            # torch or other native wheels must be rewritten in this process.
            pin_gaps = [
                p
                for p in pkgs
                if _req_base_name(p) not in native_names
                and not _requirement_satisfied(p)
            ]
            if pin_gaps:
                install_list = pin_gaps
                use_force = True
            elif probe.get("needsTorchCuda") or probe.get("needsTorchRocm"):
                return {
                    **probe,
                    "ok": False,
                    "code": "EXTRAS_REQUIRES_COLD_INSTALL",
                    "message": (
                        "Qwen3-ASR 需要改装 GPU 版 PyTorch，但依赖已加载于当前引擎进程，"
                        "无法原地重装。请停止引擎后重试一键修复 / 下载（桌面会在引擎外冷安装）。"
                    ),
                }
            else:
                return {
                    **probe,
                    "ok": False,
                    "code": "EXTRAS_LOCKED_IN_PROCESS",
                    "message": (
                        "Qwen3-ASR 运行库导入失败，但依赖已加载于当前引擎进程，"
                        "无法原地重装。请停止引擎后重试一键修复，或改用「手动安装」。"
                        f" missing={probe.get('missing')} errors={probe.get('errors')}"
                    ),
                }
        elif not retry_unsat:
            # Fresh process: force-reinstall pins to heal broken METADATA / imports.
            install_list = pkgs
            use_force = True
        else:
            unsatisfied = retry_unsat
            install_list = None  # filled below
            use_force = False
    else:
        install_list = None
        use_force = False

    if install_list is None:
        if unsatisfied:
            safe = [p for p in unsatisfied if _req_base_name(p) not in native_names]
            unsafe = [p for p in unsatisfied if _req_base_name(p) in native_names]
            # Lock only packages already mapped in *this* process. CLI/bootstrap
            # often has numpy alone (jobs→audio historically); that must not block
            # tokenizers / torch / torchaudio repairs still free to overwrite.
            loaded_bases = {name for name in native_names if name in sys.modules}
            unsafe_mapped = [
                p for p in unsafe if _req_base_name(p) in loaded_bases
            ]
            unsafe_free = [
                p for p in unsafe if _req_base_name(p) not in loaded_bases
            ]
            if unsafe_mapped and not safe and not unsafe_free:
                meta = probe_asr_qwen3()
                return {
                    **meta,
                    "ok": False,
                    "code": "EXTRAS_LOCKED_IN_PROCESS",
                    "message": (
                        "Qwen3-ASR 运行库已加载于当前引擎进程，无法原地重装"
                        "（Windows 会拒绝覆盖 DLL）。"
                        "请停止引擎后重试一键修复，或改用「手动安装」。"
                        f" missing={meta.get('missing')} errors={meta.get('errors')}"
                    ),
                }
            if loaded_bases and (safe or unsafe_free):
                install_list = [*safe, *unsafe_free]
            else:
                install_list = unsatisfied
            # Pure-python downgrades (hub 1.x / transformers 5.x) need --upgrade.
            use_force = bool(safe) and all(
                _req_base_name(p) not in native_names for p in install_list
            )
        elif force and not loaded:
            install_list = pkgs
            use_force = True
        elif loaded:
            meta = probe_asr_qwen3()
            return {
                **meta,
                "ok": False,
                "code": "EXTRAS_LOCKED_IN_PROCESS",
                "message": (
                    "Qwen3-ASR 运行库导入失败，但依赖已加载于当前引擎进程，"
                    "无法原地重装。请停止引擎后重试。"
                    f" missing={meta.get('missing')} errors={meta.get('errors')}"
                ),
            }
        else:
            install_list = unsatisfied or pkgs
            use_force = bool(force)

    if on_progress:
        try:
            on_progress(
                {
                    "type": "progress",
                    "stage": "pip",
                    "detail": (
                        "正在安装 Qwen3-ASR 运行库…"
                        + (
                            "（AMD：将校验/补齐 ROCm PyTorch + torchaudio，勿装 CUDA 版）"
                            if _amd_only_gpu()
                            else "（有 NVIDIA GPU 时将改装 CUDA 版 PyTorch，约 2.5GB）"
                        )
                    ),
                }
            )
        except Exception:
            pass

    result = _install_packages(
        install_list,
        force=use_force,
        on_progress=on_progress,
        label=" Qwen3-ASR 运行库",
    )
    # pip may have replaced transformers on disk while this process still
    # holds the pre-install LazyModule. Evict pure-Python packages only.
    _evict_imported_prefixes(_QWEN3_REPROBE_PREFIXES)
    if not result.get("ok"):
        probe_recover = probe_asr_qwen3_runtime()
        if probe_recover.get("ready"):
            return {
                "ok": True,
                **probe_recover,
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
                "recoveredAfterInstallError": True,
                "installError": str(result.get("message") or result.get("error") or "")[:400],
            }
        return result
    probe2 = probe_asr_qwen3_runtime()
    # AMD: transformers pip can leave ROCm torch host OK while torchaudio.pyd is dead.
    if (
        not probe2.get("ready")
        and _amd_only_gpu()
        and any("torchaudio" in str(e).lower() for e in (probe2.get("errors") or []))
    ):
        try:
            from .rocm_device import install_torch_rocm

            rocm_heal = install_torch_rocm(force=True, on_progress=on_progress)
            if rocm_heal.get("ok"):
                _evict_imported_prefixes(("torchaudio", "torchvision"))
                probe2 = probe_asr_qwen3_runtime()
                result = {
                    **result,
                    "torchRocmHeal": True,
                    "code": "TORCHAUDIO_ROCM_FORCE_HEAL",
                }
        except Exception as heal_err:
            result = {
                **result,
                "torchRocmHealError": str(heal_err)[:240],
            }
    pin_retry: dict[str, Any] = {"ok": True, "skipped": True}
    # Reinstalling tokenizers in this same process cannot heal a PyO3 re-init.
    if not probe2.get("ready") and not _probe_is_pyo3_reinit(probe2):
        pin_retry = _reassert_shared_runtime_pins(on_progress=on_progress)
        if pin_retry.get("ok"):
            _evict_imported_prefixes(_QWEN3_REPROBE_PREFIXES)
            probe2 = probe_asr_qwen3_runtime()
    if not probe2.get("ready"):
        meta = probe_asr_qwen3()
        if meta.get("ready") and _probe_is_pyo3_reinit(probe2):
            versions = meta.get("versions") if isinstance(meta.get("versions"), dict) else {}
            hint = (
                "Qwen3-ASR 运行库已写入磁盘（"
                + "，".join(f"{k} {v or '?'}" for k, v in versions.items())
                + "）。当前安装进程无法再次加载 tokenizers（PyO3 只能初始化一次），"
                "引擎重启后即可使用。"
            )
            return {
                "ok": True,
                **meta,
                "ready": True,
                "installed": result.get("installed") or [],
                "mirror": result.get("mirror"),
                "reprobeSkipped": "pyo3_reinit",
                "hint": hint,
                "message": hint,
            }
        return {
            **probe2,
            **{k: meta[k] for k in ("hasCudaGpu", "torchCuda") if k in meta},
            "ok": False,
            "code": probe2.get("code") or meta.get("code") or "QWEN3_RUNTIME_NOT_READY",
            "message": probe2.get("hint") or meta.get("hint") or "Qwen3-ASR 运行库安装后仍不可用",
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror"),
            "pinsReasserted": pin_retry.get("installed") if isinstance(pin_retry, dict) else None,
        }
    return {
        "ok": True,
        **probe2,
        "installed": result.get("installed") or [],
        "mirror": result.get("mirror"),
        "skipped": bool(result.get("skipped")),
        "torchCuda": result.get("torchCuda"),
    }


def ensure_extras_for_models(
    model_ids: Iterable[str] | None,
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Install pip extras required by the given catalog model ids."""
    keys = extras_for_model_ids(model_ids)
    if not keys:
        return {"ok": True, "extras": [], "results": [], "skipped": True}

    results: list[dict[str, Any]] = []
    for key in keys:
        if key == "asr-whisper":
            one = ensure_asr_whisper(force=force, on_progress=on_progress)
        elif key == "vad-whisperseg":
            one = ensure_vad_whisperseg(force=force, on_progress=on_progress)
        elif key == "asr-sensevoice":
            one = ensure_asr_sensevoice(force=force, on_progress=on_progress)
        elif key == "asr-qwen3":
            one = ensure_asr_qwen3(force=force, on_progress=on_progress)
        elif key == "mt":
            one = ensure_mt(force=force, on_progress=on_progress)
        else:
            pkgs = EXTRA_PACKAGES.get(key) or ()
            one = _install_packages(
                pkgs,
                force=force,
                on_progress=on_progress,
                label=f" {key}",
            )
            # Soft-verify only for whisper / whisperseg; other stacks are large
            # and probed at job time.
        results.append({"extra": key, **one})
        if not one.get("ok"):
            # Policy blocks on Whisper (av DLL) must not abort SenseVoice / other extras.
            if one.get("code") == "SMART_APP_CONTROL" and key == "asr-whisper":
                continue
            return {
                "ok": False,
                "code": one.get("code") or "EXTRAS_INSTALL_FAILED",
                "message": one.get("message") or f"安装 {key} 失败",
                "extras": keys,
                "results": results,
            }

    soft_policy = [
        r for r in results
        if r.get("extra") == "asr-whisper" and r.get("code") == "SMART_APP_CONTROL"
    ]
    out: dict[str, Any] = {"ok": True, "extras": keys, "results": results}
    if soft_policy:
        out["warnings"] = soft_policy
        out["message"] = soft_policy[0].get("message") or soft_policy[0].get("hint")
    return out
